WITH payload AS (SELECT $archive_payload$[{"id":"7e960c4e-1044-5662-8def-24e66186ec6f","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول لعدم النفقة، وسوء العشرة ،والكراهية -إنكار الزوج سوء العشرة وطلب إلزام الزوجة باالنقياد لبيت الزوجية -تعذر اإلصاح بن الزوجن - مين االستظهار -دفع الضرر عن الزوجة موج ب للفسخ -احلكم بفسخ النكاح على كامل املهر املسمى .","document_number":"34177797","case_number":"3412864","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/2","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول لعدم النفقة، وسوء العشرة ،والكراهية -إنكار الزوج سوء العشرة وطلب إلزام الزوجة باالنقياد لبيت الزوجية -تعذر اإلصاح بن الزوجن - مين االستظهار -دفع الضرر عن الزوجة موج ب للفسخ -احلكم بفسخ النكاح على كامل املهر املسمى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/2 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34177797 :‬‬\n                    ‫َر ْق ُم الدعوى‪3412864 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34238448‬تاريخه‪1434/6/12:‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬طلــب الزوجــة فســخ النــكاح بعــد الدخــول لعــدم النفقــة‪،‬‬\n‫وســوء العشــرة ‪ ،‬والكراهيــة ‪ -‬إنــكار الــزوج ســوء العشــرة وطلــب إلــزام‬\n‫الزوجــة باالنقيــاد لبيــت الزوجيــة ‪ -‬تعــذر اإلصــاح بــن الزوجــن ‪-‬‬\n‫ميــن االســتظهار ‪ -‬دفــع الضــرر عــن الزوجــة موجـ ٌـب للفســخ ‪ -‬احلكــم‬\n                              ‫بفســخ النــكاح علــى كامــل املهــر املســمى ‪.‬‬\n\n\n\n\n                 ‫‪ .1‬قوله تعالى‪ ( :‬فإمساك مبعروف أو تسريح بإحسان)‪.‬‬\n         ‫‪ .2‬قوله تعالى‪( :‬وال تعضلوهن لتذهبوا ببعض ما آتيتموهن)‪.‬‬\n‫‪ .3‬قولــه تعالــى‪( :‬وإن خفتــم شــقاق بينهمــا فبعثــوا حكمــا مــن أهلــه‬\n             ‫وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا)‪.‬‬\n‫‪ .4‬قولــه صلــى اهلل عليــه وســلم (أميــا امــرأة ســألت الطــاق مــن غيــر‬\n                                         ‫بــأس فحــرام عليهــا رائحــة اجلنــة)‪.‬‬\n‫‪ .5‬قولــه صلــى اهلل عليــه وســلم يف قصــة ثابــت بــن قيــس ( ملــا جــاءت‬\n‫إلــى النبــي صلــى اهلل عليــه وســلم وقالــت‪ :‬يــا رســول اهلل واهلل مــا أعتــب‬\n‫عليــه يف خلــق وال ديــن ولكنــي أكــره الكفــر يف اإلســام فقــال صلــى اهلل‬\n‫عليــه وســلم‪ :‬أترديــن عليــه حديقتــه ؟ قالــت نعــم ‪ .‬قــال‪ :‬خــذ احلديقــة‬\n                                                             ‫وطلقهــا تطليقــة )‬\n‫‪ .6‬قــال شــيخ اإلســام ابــن تيميــه رحمــه اهلل ( واحلكمــان لهمــا عنــد‬\n‫أكثــر أهــل الســلف أن يفرقــا بــن الزوجــن إذا كان ذلــك دفعــا‬\n\n                                                                                     ‫‪204‬‬\n\f      ‫للضــرر عــن الزوجــة وقــد دل علــى ذلــك الكتــاب والســنة واآلثــار وهــو‬\n                   ‫قــول مالــك وأحــد القولــن يف مذهــب الشــافعي وأحمــد )‬\n      ‫‪ .7‬قــال ابــن العربــي‪ ( :‬متــى حصــل خلــل مبقصــود النــكاح مــن عــدم‬\n      ‫األلفــة وحســن املعاشــرة وفقــد االتفــاق والتآلــف وحســن التعاشــر ســواء‬\n      ‫كان مــن قبــل الزوجــن معــا أو مــن أحدهمــا لــم يكــن لبقــاء العقــد‬\n                                            ‫وجــه وفــرق بينهمــا بعــوض أو بدونــه )‬\n      ‫‪ .8‬مــا قــرره أهــل العلــم مــن أنــه يجــوز إلــزام الــزوج بالفســخ واخللــع عنــد‬\n      ‫عــدم تــاؤم احلــال بــن الزوجــن ‪ ،‬قــال ابــن مفلــح يف الفــروع‪ :‬وبــه ألــزم‬\n                                             ‫بعــض حــكام الشــام املقادســة الفضالء‪.‬‬\n      ‫واختــار هــذا شــيخ اإلســام ابــن تيميــة والعالمــة محمــد بــن إبراهيــم‬\n                                                                            ‫آل الشــيخ ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة املعــرف بهــا مــن قبــل قســم النســاء يف احملكمــة أن‬\n      ‫املدعــى عليــه تزوجهــا وأمهرهــا ثالثــن ألــف ريــال ‪ ،‬ودخــل بهــا وتركهــا‬\n      ‫عنــد أهلهــا منــذ ســنتني مــن غيــر ســبب تعلمــه ‪ ،‬كمــا أنــه ال ينفــق عليهــا‬\n      ‫وال يراهــا وال تــراه كاألجنبيــة ‪ ،‬وأنهــا تضــررت مــن ذلــك كثيــراً‪،‬‬\n      ‫وطلبــت فســخ نكاحهــا منــه ‪ ،‬بعــرض دعــوى املدعيــة علــى املدعــى عليــه‬\n      ‫صــادق علــى الــزواج واملهــر والدخــول وأنكــر ســوء العشــرة‪ ،‬وقــرر عــدم‬\n      ‫موافقتــه علــى طلبهــا الفســخ ‪ ،‬وطلــب إلــزام املدعــى عليهــا باالنقيــاد‬\n      ‫إلــى بيــت الطاعــة والزوجيــة ‪ ،‬جــرى نصــح الزوجــن بتقــوى اهلل عـ َّـز‬\n      ‫وجــل يف الســر والعلــن وتذكيــر املدعيــة بقولــه صلــى اهلل عليــه وســلم‬\n      ‫( أميــا امــرأة ســألت الطــاق مــن غيــر بــأس فحــرام عليهــا رائحــة اجلنــة)‬\n\n‫‪205‬‬\n\f‫فقــررت أنهــا تكــره الــزوج كره ـ ًا شــديد ًا ولــم يقــذف اهلل يف قلبهــا‬\n‫محبــة ومــودة‪ ،‬وأن اخلــاف بينهمــا كثيــر ‪ ،‬كمــا جــرى نصــح الــزوج‬\n‫وتذكيــره بقولــه تعالــى (فإمســاك مبعروف أو تســريح بإحســان) وبقوله‬\n‫(وال تعضلوهــن لتذهبــوا ببعــض مــا آتيتموهــن) فقــرر أنــه يريــد زوجتــه‬\n‫‪ ،‬ولقولــه تعالــى (وإن خفتــم شــقاق بينهمــا فبعثــوا حكمــا مــن أهلــه‬\n‫وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا) قــرر الزوجــان‬\n‫أن يكــون احلكمــان بينهمــا قســم اإلصــاح يف احملكمــة‪ ،‬ومــا يقــرره‬\n‫يكــون ملزم ـ ًا للطرفــن‪ ،‬ليــس ألحــدٍ االعتــراض عليــه ‪ ،‬ورد جــواب‬\n‫قســم اإلصــاح املتضمــن تعــذر الصلــح بــن الطرفــن‪ ،‬ورأوا أن تخالــع‬\n‫الزوجــة زوجهــا مقابــل رد املهــر املســمى يف عقــد النــكاح وقــدره خمســة‬\n‫وثالثــون ألــف ‪ ،‬بعــرض ذلــك علــى الطرفــن قــررت املدعيــة قناعتهــا‬\n‫ورضاهــا بــه‪ ،‬وقــرر املدعــى عليــه عــدم رضــاه بــه ‪ ،‬بنــاء علــى قــرار‬\n‫ـب‬\n ‫احلكمــن ومــا قــرره أهــل العلــم مــن أن دفــع الضــرر عــن الزوجــة موجـ ٌ‬\n‫للفســخ إذا رأى ذلــك احلكمــان‪ ،‬وأنــه يجــوز إلــزام الــزوج بالفســخ واخللــع‬\n‫عنــد عــدم تــاؤم احلــال بــن الزوجــن ‪ ،‬اســتعداد الزوجــة بدفــع كامــل‬\n‫املهــر املســمى يف العقــد ‪ ،‬لــذا مت احلكــم بفســخ نــكاح املدعيــة مــن‬\n‫زوجهــا املدعــى عليــه بكامــل املهــر املســمى يف العقــد وقــدره خمســة‬\n‫وثالثــون ألــف ريــال وجــرى إفهــام املدعيــة بــأن عليهــا العدة الشــرعية وأن‬\n‫ال تســتجيب خلاطــب وال راغــب حتــى يكتســب احلكــم القطعيــة بعــرض‬\n‫احلكــم علــى الطرفــن قــررت املدعيــة القناعــة والرضــا بــه وأمــا املدعــى‬\n‫عليــه فلــم يقنــع وطلــب رفعــه حملكمــة التمييــز بالئحــة اعتراضيــة ‪،‬‬\n            ‫بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n                                                                                    ‫‪206‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪ ..‬وبعــد‪ :‬فلــدي‬\n      ‫أنــا (‪ ).......‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن فضيلــة رئيس احملكمة العامــة مبحافظة جدة‪/‬‬\n      ‫املســاعد برقــم ‪ 3412864‬وتاريــخ ‪ 1434/01/07‬ه ـ املقيــدة باحملكمة‬\n      ‫برقــم ‪ 3459864‬وتاريــخ ‪ 1434/01/07‬ه ـ ففــي يــوم الســبت املوافــق‬\n      ‫‪1434/02/09‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 30‬وفيهــا حضــرت‬\n      ‫(‪ ).......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).......‬واملعــرف‬\n      ‫بهــا مــن قبــل قســم النســاء يف هــذه احملكمــة فادعــت ضــد الغائــب عــن‬\n      ‫مجلــس القضــاء (‪ ).......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ).......‬قائلــة يف تقريــر دعواهــا ضــده‪ :‬إن هــذا الغائــب عــن مجلــس‬\n      ‫القضــاء هــو زوجــي تزوجنــي مبوجــب العقــد الصحيــح‪ ،‬وأمهرنــي مبلغـ ًا‬\n      ‫قــدره ثالثــون ألــف ريــال ‪ ،‬ودخــل بــي الدخــول الشــرعي‪ ،‬وقــد تركنــي‬\n      ‫املدعــى عليــه عنــد أهلــي منــذ ســنتني مــن غيــر ســبب أعلمــه‪ ،‬علمـ ًا أنــه‬\n      ‫ال ينفــق علـ َّـي وال يرانــي وال أراه كاألجنبيــة‪ ،‬وقــد تضــررت مــن ذلــك‬\n      ‫كثيــراً‪ .‬لــذا أطلــب مــن فضيلتكــم فســخ نكاحــي منــه‪ ،‬وحيــث لــم‬\n      ‫يحضــر املدعــى عليــه وال مــن ينــوب عنــه‪ ،‬ولــم يردنــا مــا يفيــد تبلغــه‪،‬‬\n      ‫وبنــاء عليــه رفعــت اجللســة ‪ ،‬ويف تاريــخ ‪1434/2/25‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 10 : 30‬وفيهــا حضــر الطرفــان وبعــرض دعــوى املدعيــة علــى‬\n      ‫املدعــى عليــه أجــاب قائــا‪ :‬ما ذكرته املدعية مــن أني تزوجتها مبوجب‬\n      ‫العقــد الصحيــح املذكــور أعــاه‪ ،‬وأمهرتهــا املهــر املذكــور أعــاه‪،‬‬\n      ‫ودخلــت بهــا الدخــول الشــرعي‪ ،‬فهــذا صحيــح‪ ،‬وأمــا مــا ذكرتــه مــن أن‬\n\n‫‪207‬‬\n\f‫ســوء العشــرة إمنــا هــو بســببي فغيــر صحيــح‪ .‬لــذا أطلــب مــن فضيلتكــم‬\n‫إلــزام املدعــى عليهــا باالنقيــاد إلــى بيــت الطاعــة والزوجيــة وأنــا ال أوافــق‬\n‫علــى فســخ النــكاح‪ .‬هكــذا أجــاب‪ .‬فجــرى منــي نصــح الزوجــن بتقــوى‬\n‫اهلل َّعــز وجــل يف الســر والعلــن وذكــرت املدعيــة بقولــه صلــى اهلل عليــه‬\n‫وســلم (( أميــا امــرأة ســألت الطــاق مــن غيــر بــأس فحــرام عليهــا رائحــة‬\n‫اجلنــة )) فقالــت‪ :‬أنــا أكــره الــزوج كره ـ ًا شــديد ًا ولــم يقــذف اهلل يف‬\n‫قلبــي محبــة ومــودة‪ ،‬واخلــاف بيننــا كثيــر‪ ،‬كمــا جــرى منــي نصــح‬\n‫الــزوج وذكرتــه بقولــه تعالــى (( فإمســاك مبعــروف أو تســريح بإحســان‬\n‫)) وبقولــه (( وال تعضلوهــن لتذهبــوا ببعــض مــا آتيتموهــن )) فقــال‪:‬‬\n‫أنــا أريــد زوجتــي وحيــث حصــل اخلــاف بــن الزوجــن واســتناد ًا لقولــه‬\n‫تعالــى (( وإن خفتــم شــقاق بينهمــا فبعثــوا حكمــا مــن أهلــه وحكمــا‬\n‫مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا )) فقــرر الزوجــان أن‬\n‫يكــون احلكمــان بينهمــا قســم اإلصــاح يف هــذه احملكمــة‪ ،‬ومــا‬\n‫يقــرره يكــون ملزم ـ ًا للطرفــن‪ ،‬ليــس ألحــدٍ االعتــراض عليــه‪ ،‬وبنــاء‬\n‫عليــه رفعــت اجللســة‪ ،‬ويف تاريــخ ‪ 1434/04/02‬ه ـ افتتحــت اجللســة‬\n‫الســاعة‪ 12:00‬وفيهــا حضــر الطرفــان‪ ،‬فوردنــا اجلــواب منهــم برقــم‬\n‫‪ 3459864‬يف ‪1434/3/16‬ه ـ وهــذا نصــه‪ « :‬فإنــه يف يــوم االثنــن‬\n‫املوافــق ‪1434/03/16‬ه ـ وبعــد محاولــة اإلصــاح بينهمــا تعــذر ذلــك‬\n‫إلصــرار املــرأة علــى طلــب املخالــة ومتســك املدعــى عليــه بزوجتــه لذلــك‬\n‫نــرى أن تخالــع الزوجــة زوجهــا مقابــل رد املهــر املســمى يف عقــد النــكاح‬\n‫وقــدره خمســة وثالثــون ألــف ريــال والــرأي لفضيلتكــم « واهلل املوفــق‬\n‫‪ .‬وبعــرض ذلــك علــى الطرفــن قــررت املدعيــة قناعتهــا ورضاهــا بــه‬\n‫وقالــت‪ :‬ال مانــع لــدي مــن دفــع كامــل املهــر وقــدره خمســة وثالثــون‬\n\n\n                                                                                         ‫‪208‬‬\n\f      ‫ألــف ريــال حيــث أنــي أكــره الــزوج كرهــا شــديدا‪ .‬كمــا قــرر املدعــى‬\n      ‫عليــه عــدم رضــاه بــه وقــال‪ :‬للمدعيــة احلــق يف طلبهــا اخللــع وأنــا أطالــب‬\n      ‫بزوجتــي علمـ ًا أنــه ســبق وأن مت الصلــح بيننــا على أن تعــود لبيت الزوجية‬\n      ‫والطاعــة وســلمتها مبلغ ـ ًا قــدره عشــرة آالف ريــال رضــوة بســبب ذلــك‪،‬‬\n      ‫فطلبــت مــن املدعيــة ميــن االســتظهار علــى كرههــا لزوجهــا فحلفــت‬\n      ‫قائلــة‪ ((:‬واهلل العظيــم الــذي ال إلــه غيــره أنــي مــا طلبــت فســخ النــكاح‬\n      ‫مــن عصمــة املدعــى عليــه إال مــن أجــل أنــي أكرهــه كرهــا شــديدا‬\n      ‫وســاءت العشــرة بيننا))‪...‬يتبــع‪ ...‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة واالطــاع علــى أوراق املعاملــة وحيــث طلبــت املدعيــة فســخ‬\n      ‫نكاحهــا مــن عصمــة زوجهــا بكامــل املهــر لكونهــا تكــره زوجهــا‬\n      ‫كرهــا شــديدا‪ ،‬وحيــث رفــض املدعــى عليــه ذلــك ولقولــه صلــى اهلل‬\n      ‫عليــه وســلم يف قصــة ثابــت بــن قيــس ( ملــا جــاءت إلــى النبــي صلــى اهلل‬\n      ‫عليــه وســلم وقالــت‪ :‬يــا رســول اهلل واهلل مــا أعتــب عليــه يف خلــق وال‬\n      ‫ديــن ولكنــي أكــره الكفــر يف اإلســام فقــال صلــى اهلل عليــه وســلم‪:‬‬\n      ‫أترديــن عليــه حديقتــه ؟ قالــت نعــم ‪ .‬قــال‪ :‬خــذ احلديقــة وطلقهــا تطليقــة‬\n      ‫) وبنــاء علــى قــرار احلكمــن املرصــود أعــاه‪ ،‬وملــا قــرره أهــل العلــم مــن‬\n      ‫أن دفــع الضــرر عــن الزوجــة موجــب للفســخ إذا رأى ذلــك احلكمــان قــال‬\n      ‫شــيخ اإلســام ابــن تيميــه رحمــه اهلل ( واحلكمــان لهمــا عنــد أكثــر‬\n      ‫أهــل الســلف أن يفرقــا بــن الزوجــن إذا كان ذلــك دفعــا للضــرر عــن‬\n      ‫الزوجــة وقــد دل علــى ذلــك الكتــاب والســنة واآلثــار وهــو قــول مالــك‬\n      ‫وأحــد القولــن يف مذهــب الشــافعي وأحمــد ) وقــال ابــن العربــي‪ ( :‬متــى‬\n      ‫حصــل خلــل مبقصــود النــكاح مــن عــدم األلفــة وحســن املعاشــرة وفقــد‬\n      ‫االتفــاق والتآلــف وحســن التعاشــر ســواء كان مــن قبــل الزوجــن معــا أو‬\n\n\n‫‪209‬‬\n\f‫مــن أحدهمــا لــم يكــن لبقــاء العقــد وجــه وفــرق بينهمــا بعــوض أو بدونــه‬\n‫) وحيــث قــرر أهــل العلــم علــى أنــه يجــوز إلــزام الــزوج بالفســخ واخللــع‬\n‫عنــد عــدم تــاؤم احلــال بــن الزوجــن قــال ابــن مفلــح يف الفــروع وبــه ألــزم‬\n‫بعــض حــكام الشــام املقادســة الفضــاء واختــار هــذا شــيخ اإلســام ابن‬\n‫تيميــة والعالمــة محمــد بــن إبراهيــم آل الشــيخ‪ .‬وحيــث اســتعدت بدفــع‬\n‫كامــل املهــر املســمى يف العقــد املذكــور أعــاه وقــدره خمســة وثالثــون‬\n‫ألــف ريــال‪ .‬لــذا فقــد فســخت نــكاح ‪............‬مــن عصمــة زوجهــا ‪...........‬‬\n‫بكامــل املهــر املســمى يف العقــد وقــدره خمســة وثالثــون ألــف ريــال‬\n‫وأفهمــت املدعيــة بــأن عليهــا العــدة الشــرعية حســب حالهــا وأفهمتهــا أن‬\n‫ال تســتجيب خلاطــب وال راغــب حتــى يكتســب احلكــم القطعيــة وبذلــك‬\n‫حكمــت وبعرضــه علــى الطرفــن قــررت املدعيــة القناعــة والرضــا بــه‬\n‫وأمــا املدعــى عليــه فلــم يقنــع وطلــب رفعــه حملكمــة التمييــز بالئحــة‬\n‫اعتراضيــة فأجبتــه لطلبــه وأفهمتــه بتعليمــات التمييــز وجــرى تســليمه‬\n‫صــورة مــن صــك احلكــم لالعتــراض عليــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/2‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده‪ ..‬وبعــد‪ :‬فقــد‬\n‫وردتنــا املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة بخطابهــم‬\n‫رقــم ‪ 3459864‬يف ‪1434/06/21‬ه ـ مرفقـ ًا بــه القــرار رقــم ‪34238448‬‬\n‫يف ‪1434/06/12‬ه ـ املظهــر علــى صــك احلكــم واملتضمــن بعــد املقدمــة‬\n‫مــا نصــه» وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n‫املوافقــة علــى احلكــم «‪ .‬لــذا جــرى إثبــات ذلــك حتــى ال يخفــى‪ ،‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n‫يف ‪1434/06/28‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــن ال‬\n\n\n                                                                                       ‫‪210‬‬\n\f      ‫نبــي بعــده ‪ ،‬وبعــد ‪ :‬نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية‬\n      ‫واألوقــاف والوصايــا والقصــار وبيــوت املــال يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة‬\n      ‫إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة‬\n      ‫املســاعد رقــم ‪ 3459864‬وتاريخ‪1434/5/8‬ه ـ املشــتملة علــى الصــك‬\n      ‫رقــم ‪ 34177797‬وتاريــخ ‪1434/4/2‬ه ـ الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة العامــة بجــدة الشــيخ‪ ........... /‬املتضمــن دعــوى ‪ ..........‬ضــد‬\n      ‫‪ ..........‬يف فســخ نــكاح وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n      ‫االعتراضيــة تقــرر املوافقــة علــى احلكــم مــع التنبيــه املرفــق ‪ ،‬واهلل‬\n           ‫املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪211‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":204,"source_page_end":211,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aa8d73bfa4dabaa44ca2361c810a47d159e808e73aa4b1082c7973e812e3babc","normalized_text_hash":"b33871fa152ed9b7f0feade058b8fd5435ab395e498a28c3be10af55a085c179","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p204-34177797"},{"id":"2a4db46f-970e-5af8-9940-906f7a777432","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول لعدم النفقة، ولترك الصاة ،وتعاطي املسكرات واملخدرات -إنكار الزوج -شهادة الشهود العدول -احلكم بفسخ النكاح -الزواج دون أخذ اجلهة النظامية مخالفة نظامية توجب احملاسبة .","document_number":"34260752","case_number":"3470131","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بصبيا","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/5","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول لعدم النفقة، ولترك الصاة ،وتعاطي املسكرات واملخدرات -إنكار الزوج -شهادة الشهود العدول -احلكم بفسخ النكاح -الزواج دون أخذ اجلهة النظامية مخالفة نظامية توجب احملاسبة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/7/5 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34260752 :‬‬\n                    ‫َر ْق ُم الدعوى‪3470131 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 35114257‬تاريخه‪1434/8/8:‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬طلــب الزوجــة فســخ النــكاح بعــد الدخــول لعــدم النفقــة‪،‬‬\n‫ولتــرك الصــاة‪ ،‬وتعاطــي املســكرات واملخــدرات ‪ -‬إنــكار الــزوج‪ -‬شــهادة‬\n‫الشــهود العــدول ‪ -‬احلكــم بفســخ النــكاح ‪ -‬الــزواج دون أخــذ اجلهــة‬\n                          ‫النظاميــة مخالفــة نظاميــة توجــب احملاســبة ‪.‬‬\n\n\n\n\n ‫‪ .1‬قوله تعالى‪ ( :‬أفمن كان مؤمنا كمن كان فاسقا ال يستوون) ‪.‬‬\n‫‪ .2‬املــواد رقــم ‪ 1/55‬و‪ 4،5/176‬و‪ 178‬مــن نظــام املرافعــات الشــرعية‪،‬‬\n                                              ‫ولوائحــه التنفيذيــة ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة املعــرف بهــا مــن قبــل زوج والدهــا ‪ ،‬أن املدعــى عليــه‬\n‫تزوجهــا بطريقــة غيــر نظاميــة بعقــد عــادي‪ ،‬ولــم تــرزق منــه بذريــة‪،‬‬\n‫وأنهــا بقيــت يف منزلــه مــدة أربعــة أشــهر ثــم هجرهــا يف بيــت أهلهــا حــن‬\n‫طالبتــه بســكن مناســب‪ ،‬وأنــه كان يســكنها ســيارة‪ ،‬وتركهــا دون‬\n‫نفقــة‪ ،‬وهــو مــازم للمســكرات واحلبــوب وتــارك للصــاة‪ ،‬وطلبــت‬\n‫إلزامــه بطالقهــا ‪ ،‬بعــرض ذلــك علــى املدعــى عليــه صــادق علــى الــزواج‬\n‫وعــدم األوالد‪ ،‬وأنكــر مــا ســوى ذلــك‪ ،‬وقــرر أنــه كان يســكنها يف‬\n‫شــقة‪ ،‬ثــم بعــد شــهرين جلســت يف بيــت أهلهــا ورفضــت الذهــاب معه إلى‬\n\n                                                                                    ‫‪212‬‬\n\f      ‫بيــت والدتــه الــذي يســكن فيــه‪ ،‬وأمــا النفقــة فقــد تــرك عندهــا ثمانيــة‬\n      ‫وأربعــن رأســا مــن الغنــم ‪ ،‬كمــا أتاهــا بنقــود وأدخلهــا مــن حتــت البــاب‬\n      ‫فردتهــا‪ ،‬وقــرر أنــه محافــظ علــى الصــاة‪ ،‬وال يتعاطــى املســكرات‬\n      ‫وال احلبــوب‪ ،‬وأنــه غيــر مســتعد بطــاق املدعيــة ‪ ،‬وطلــب رد دعواهــا ‪،‬‬\n      ‫بعــرض دفــع املدعــى عليــه علــى املدعيــة أجابــت أنهما ســكنا يف العمارة‬\n      ‫التــي ذكرهــا أيــام الفــرح وبعدهــا كانــوا ينامــون يف الســيارة‪ ،‬وأمــا‬\n      ‫الغنــم فقــد وضعهــا يف بيــت أهلهــا وكان كل أســبوع يأخــذ عــددا منهــا‬\n      ‫مــن ســت إلــى ثمــان ويبيعهــا ويشــتري أغراضــه اخلاصــة ومنهــا املســكر‬\n      ‫ويعطيهــا مائــة ريــال‪ ،‬وأمــا الصــاة فهــو ال يصلــي وال يصــوم وكذلــك‬\n      ‫ـاط للمســكرات واحلبــوب ‪ ،‬بطلــب البينــة مــن املدعيــة أحضــرت‬          ‫متعـ ٍ‬\n      ‫شــاهدين‪ ،‬ومت ســماع شــهادتهما‪ ،‬وبعرضهــا علــى املدعــى عليــه طعــن‬\n      ‫يف الشــهود‪ ،‬وكــذب الشــهادة‪ ،‬ومت تعديــل الشــهود ‪ ،‬يف جلســة أخــرى‬\n      ‫حضــرت املدعيــة‪ ،‬وغــاب املدعــى عليــه ‪ ،‬شــهادة الشــهود املعدلــن علــى‬\n      ‫تــرك املدعــى عليــه الصــاة ووقوعــه يف املســكرات وهــذا نقــص يف‬\n      ‫الديــن ال يســوغ معــه بقــاء الزوجيــة أخــذا مــن قــول اهلل جــل وعــا (‬\n      ‫أفمــن كان مؤمنــا كمــن كان فاســقا ال يســتوون ) مــع مــا فيــه مــن‬\n      ‫ضــرر علــى الزوجــة ‪ ،‬لــذا مت احلكــم بفســخ نــكاح املدعيــة مــن املدعــى‬\n      ‫عليــه وجــرى إفهــام املدعيــة أن عليهــا العــدة الشــرعية اعتبــارا مــن تاريــخ‬\n      ‫احلكــم‪ ،‬وأن ال تتــزوج حتــى يكتســب احلكــم القطعيــة ‪ ،‬وأن زواجهما‬\n      ‫الســابق دون أخــذ إذن مــن اجلهــة املختصــة يعــد مخالفة نظامية يحاســبان‬\n      ‫عليهــا‪ ،‬وأن هــذا الصــك للفصــل يف القضيــة وال ميكــن االعتمــاد عليــه‬\n      ‫فيمــا ســوى ذلــك وال يعتبــر مســتندا رســميا ملــا ســوى ذلــك ‪ ،‬الكتابــة‬\n      ‫للحاكــم اإلداري إلجــراء الــازم حيــال املخالفــة النظاميــة ‪ ،‬يعتبــر هــذا‬\n\n\n‫‪213‬‬\n\f‫احلكــم يف حــق املدعــى عليــه حضوري ـ ًا ‪ -‬بعــد رفــع احلكــم حملكمــة‬\n                                        ‫االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).......‬القاضــي باحملكمــة‬\n‫العامــة بصبيــا وبنــاء علــى املعاملــة احملــدث قيدهــا باحملكمــة برقــم‬\n‫‪ 34352125‬وتاريــخ ‪1434/2/11‬ه ـ واحملالــة إلــى مكتبنــا برقــم ‪2813‬‬\n‫يف ‪1433/7/30‬ه ـ واملقيــدة مبكتبنــا برقــم ‪ 1646‬يف ‪1433/7/30‬ه ـ‬\n‫ويف يــوم األربعــاء املوافــق ‪1433/11/10‬ه ـ افتتحــت اجللســة الســاعة‬\n‫التاســعة والنصــف وفيهــا حضــرت (‪ ).......‬ال حتمــل هويــة املعــرف بهــا مــن‬\n‫قبــل زوج والدتهــا (‪ ).......‬وابنــه (‪ ).......‬وحضــر حلضورهــا (‪ ).......‬ســعودي‬\n‫اجلنســية فادعــت قائلــة إن هــذا احلاضــر زوجــي تزوجنــي بطريقــة غيــر‬\n‫نظاميــة بعقــد عــادي يف ‪1431/9/6‬ه ـ ولــم أرزق منــه بذريــة وقــد بقيــت‬\n‫يف منزلــه ملــدة أربعــة أشــهر ثــم يف عــام ‪1432‬ه ـ هجرنــي يف بيــت أهلــي‬\n‫حــن طالبتــه بســكن مناســب وقــد كان قبلهــا يســكنني ســيارة وقــد‬\n‫تركنــي دون نفقــة كمــا أنــه مــازم للمســكرات واحلبــوب وتــارك‬\n‫للصــاة وأطلــب إلزامــه بطالقــي هــذه دعــواي وبعــرض ذلــك على املدعى‬\n‫عليــه أجــاب بقولــه مــا ذكرتــه املدعيــة مــن زواجــي بهــا يف التاريــخ‬\n‫املذكــور وعــدم وجــود أوالد فهــو صحيــح ولكــن مــا ســواه غيــر صحيــح‬\n‫فقــد كنــت أســكنها معــي ملــدة شــهرين يف شــقق ‪ ........‬بصبيــا وبعــد‬\n‫شــهرين كانــت جتلــس يف بيــت أهلهــا وترفــض الذهــاب معــي إلــى بيــت‬\n‫والدتــي الــذي أســكن فيــه وأمــا النفقــة فقــد تركــت عندهــا ثمانيــة‬\n‫وأربعــن رأســا مــن الغنــم ثــم أتيتهــا بنقــود وأدخلتهــا مــن حتــت البــاب‬\n\n                                                                                     ‫‪214‬‬\n\f      ‫فردتهــا وأمــا الصــاة فأنــا محافــظ عليهــا وال أتعاطــى املســكرات وال‬\n      ‫احلبــوب وغيــر مســتعد بطــاق املدعيــة أطلــب رد دعواهــا هكــذا أجــاب‬\n      ‫وبعرضــه علــى املدعيــة أجابــت أمــا موضــوع الســكن فقــد ســكنا يف‬\n      ‫العمــارة التــي ذكرهــا أيــام الفــرح وبعدهــا كنــا ننــام يف الســيارة كمــا‬\n      ‫ذكــرت يف دعــواي وأمــا الغنــم فقــد وضعهــا عنــد بيــت أهلــي وكان‬\n      ‫كل أســبوع يأخــذ عــددا منهــا مــن ســت إلــى ثمــان ويبيعهــا ويشــتري‬\n      ‫أغراضــه اخلاصــة ومنهــا املســكر ويعطينــي مائــة ري ــال وأمــا الصــاة‬\n      ‫فهــو ال يصلــي وال يصــوم وكذلــك متعــاط للمســكرات واحلبــوب ولــدي‬\n      ‫البينــة علــى ذلــك فطلبــت منهــا إحضارهــا يف اجللســة القادمــة ويف جلســة‬\n      ‫أخــرى حضــر الطرفــان فجــرى ســؤال املدعيــة هــل أحضــرت مــا طلــب‬\n      ‫منهــا فأجابــت إننــي قــد أحضــرت ‪ ...........‬وابنــه ‪ .....‬هــذا وقــد حضــر يف‬\n      ‫هــذه اجللســة ‪ ..........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪ ............‬وقــد‬\n      ‫عــرف بنفســه بــأن عمــره تســعة وأربعــون عامــا وهــو متقاعــد ويســكن‬\n      ‫الريــاض وهــو أخ املدعــى عليــه واملدعيــة ربيبتــه ابنــة زوجتــه وبســؤاله‬\n      ‫عمــا لديــه مــن شــهادة شــهد قائــا أشــهد هلل تعالــى أن املدعــى عليــه‬\n      ‫أخــي وهــو متعــاط للمســكر تــارك للصــاة أشــهد بــاهلل تعالــى علــى‬\n      ‫ذلــك وبعــرض ذلــك علــى املدعــي أجــاب هــذا الشــاهد شــهادته غيــر‬\n      ‫مقبولــة فهــو بيــاع للمخــدرات وتــارك للصــاة وقــد كــذب علــي ولكنــي‬\n      ‫صــادق فيمــا أقولــه وبســؤاله هــل لديــه بينــة علــى مــا طعــن بــه أجــاب‬\n      ‫ليــس لــدي هــذا كمــا حضــر يف هــذه اجللســة ‪ ..........‬ســعودي بالســجل‬\n      ‫املدنــي رقــم ‪ .......‬وقــد عــرف بنفســه أن عمــره ســتة عشــر عامــا وأنــه‬\n      ‫كان طالبــا وحاليــا ال يعمــل ويســكن نخــان واملدعيــة أختــه ألمــه‬\n      ‫واملدعــى عليــه عمــه وبســؤاله عمــا لديــه مــن شــهادة شــهد قائــا أشــهد‬\n\n\n‫‪215‬‬\n\f‫هلل تعالــى أن عمــي املدعــى عليــه تــارك للصــاة وكنــت أراه يف حالــة‬\n‫ســكر يف الفتــرة املاضيــة إلــى مــا قبــل شــهرين مــن اآلن أشــهد بــاهلل‬\n‫تعالــى علــى ذلــك وبعــرض ذلــك علــى املدعــى عليــه أجــاب إن الشــاهد‬\n‫متعــاط للمســكر ولــدي شــاهد وهــو ‪ ..........‬فأفهمتــه بإحضــار شــاهد‬\n‫الطعــن كمــا أفهمــت املدعيــة بإحضــار معدلــن لشــهودها ويف جلســة‬\n‫أخــرى حضــر الطرفــان فجــرى ســؤال املدعــى عليــه هــل أحضــر شــهود‬\n‫الطعــن فأجــاب إنــه تعــذر علــي إحضارهــم وأطلــب إمهالــي كمــا أجابــت‬\n‫املدعيــة إننــا لــم نحضــر املعدلــن للشــهود وعليــه فقــد جــرى حتديــد مهلــة‬\n‫أخيــرة للطرفــن إلحضــار مــا طلــب منهمــا ويف جلســة أخــرى حضــرت‬\n‫املدعيــة املعــرف بهــا مــن قبــل زوج والدتهــا عقيــل املثبتــة هويتــه أعــاه‬\n‫ولــم يحضــر املدعــى عليــه أو يحضــر مــا طلــب منــه رغــم توقيعــه علــى‬\n‫الضبــط يف اجللســة املاضيــة وقــد أحضــرت املدعيــة معهــا كال مــن‬\n‫‪.........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..........‬و‪.........‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..........‬وشــهد كل واحــد‬\n‫منهمــا بقولــه أشــهد هلل تعالــى أننــي أعــرف الشــاهدين ‪ ...........‬وابنــه‬\n‫‪ ........‬وهمــا ثقتــان عــدالن مقبــوال الشــهادة ولــو شــهدا علــي لــم أطعــن‬\n‫فيهمــا بشــيء هكــذا شــهدا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫ومــا تضمنتــه دعــوى املدعيــة وطلبهــا فســخ النــكاح مــن املدعــى عليــه‬\n‫لألســباب املذكــورة يف الدعــوى ولشــهادة الشــهود املعدلــن علــى تــرك‬\n‫املدعــى عليــه الصــاة ووقوعــه يف املســكرات وألن ذلــك كلــه نقــص‬\n‫يف الديــن ال يســوغ معــه بقــاء الزوجيــة أخــذا مــن قــول اهلل جــل وعــا (‬\n‫أفمــن كان مؤمنــا كمــن كان فاســقا ال يســتوون ) كمــا أن فيــه فقدا‬\n‫للكفــاءة مــع مــا فيــه مــن ضــرر علــى الزوجــة ولذلــك كلــه فقــد فســخت‬\n\n\n                                                                                     ‫‪216‬‬\n\f      ‫نــكاح املدعيــة ‪..........‬مــن املدعــى عليــه ‪ ........‬ومبــا ذكــر حكمــت‬\n      ‫وأفهمــت املدعيــة أن عليهــا العــدة الشــرعية حســب حالهــا اعتبــارا مــن‬\n      ‫تاريــخ هــذا اليــوم كمــا أفهمتهــا أن عليهــا أن ال تتــزوج حتــى يكتســب‬\n      ‫هــذا احلكــم القطعيــة بتصديقــه أو انتهــاء مــدة االعتــراض فقــررت‬\n      ‫فهمهــا لذلــك كمــا قــررت بعــث نســخة مــن صــك احلكــم للمدعــى‬\n      ‫عليــه ليقــدم اعتراضــه خــال املــدة املقــررة نظام ـ ًا وهــي ثالثــون يوم ـ ًا‬\n      ‫مــن تاريــخ التبليــغ وأنــه إذا مضــت مــدة االعتــراض ولــم يقــدم اعتراضــه‬\n      ‫فــإن احلكــم يكتســب القطعيــة ويعــد حضوري ـ ًا يف حــق املدعــى عليــه‬\n      ‫حســب املــواد رقــم ‪ 1/55‬و‪ 4/176‬و‪ 178‬مــن الالئحــة التنفيذيــة لنظــام‬\n      ‫املرافعــات هــذا كمــا أفهمــت املدعيــة أن زواجهمــا الســابق دون أخــذ‬\n      ‫إذن مــن اجلهــة املختصــة يعــد مخالفــة نظاميــة يحاســبان عليهــا وأن‬\n      ‫عليهمــا مراجعــة اجلهــة املختصــة ألخــذ اإلذن قبــل عقــد النــكاح كمــا‬\n      ‫أفهمتهمــا أن هــذا الصــك للفصــل يف القضيــة وال ميكــن االعتمــاد‬\n      ‫عليــه فيمــا ســوى ذلــك وال يعتبــر مســتندا رســميا ملــا ســوى ذلــك هــذا‬\n      ‫كمــا قــررت الكتابــة للحاكــم اإلداري إلجــراء الــازم حيــال املخالفــة‬\n      ‫النظاميــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/24‬ه ـ الســاعة الثانيــة عشــرة والربــع‬\n      ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم األربعــاء املوافــق ‪1434/12/4‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة التاســعة وحيــث قــد وردنــا خطــاب رئيــس‬\n      ‫احملكمــة العامــة بالريــاض املســاعد رقــم ‪ 342064605‬يف‬\n      ‫‪1434/11/10‬ه ـ املرفــق بــه إفــادة محضــري اخلصــوم املتضمنــة « أنــه‬\n      ‫مت االتصــال أكثــر مــن مــرة علــى جــوال املدعــى عليــه ووجــد أنــه مغلــق»‬\n      ‫وعليــه ونظــرا ألنــه تعــذر تســليمه نســخة مــن صــك احلكــم عــن طريــق‬\n\n\n‫‪217‬‬\n\f‫احملضريــن فقــد أمــرت برفــع املعاملــة إلــى محكمــة االســتئناف بنــاء‬\n‫علــى املــادة ‪ 5/176‬مــن نظــام املرافعــات الشــرعية وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                              ‫‪1434/12/4‬ه ـ الســاعة التاســعة والنصــف‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واألوقــاف والوصايــا والقصــار‬\n‫وبيــوت املــال مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة لهــذه احملكمــة مــن فضيلــة رئيــس احملكمــة العامــة بصبيــا‬\n‫برقــم ‪ 34352125‬وتاريــخ ‪1434/12/18‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة الشــيخ (‪ ).......‬رقــم‪ 34260752‬وتاريــخ ‪1434/7/5‬ه ـ‬\n‫اخلاصــة بدعــوى (‪ ).......‬ضــد (‪ ).......‬بشــأن فســخ نــكاح علــى الصفــة‬\n‫املوضحــة بالصــك واملتضمــن حكــم فضيلتــه مبــا هــو مــدون بباطنــه‬\n‫وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى‬\n‫احلكــم مــع التنبيــه املرفــق واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n‫وآلــه وصحبــه وســلم ‪ .‬دائــرة األحــوال الشــخصية واألوقــاف والوصايــا‬\n                                                   ‫والقصــار وبيــوت املــال ‪.‬‬\n\n\n\n\n                                                                                  ‫‪218‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":212,"source_page_end":218,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"11b682f153d5e2fbce92cae4bbfee122e592d41a10fa73aff524101b05c971d4","normalized_text_hash":"ba689f45d7c3eb153b762fe6344284936ebb23bb8332e2f8f66e90bc981c56a5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p212-34260752"},{"id":"018ccb7b-18c1-5a67-88e0-1eae17d056f9","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -مطالبة بفسخ نكاح للضرب وشرب اخلمر وعدم النفقة والكراهية -تعذر الصلح بن الزوجن -احلكم بالفسخ مقابل تنازل الزوجة عن املؤخر ونفقتها ونفقة األوالد املاضية .","document_number":"34255305","case_number":"3498431","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض والقائم بعمل املكتب القضائي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/1","year":"1434","subject":"فسخ نكاح -مطالبة بفسخ نكاح للضرب وشرب اخلمر وعدم النفقة والكراهية -تعذر الصلح بن الزوجن -احلكم بالفسخ مقابل تنازل الزوجة عن املؤخر ونفقتها ونفقة األوالد املاضية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/1 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34255305 :‬‬\n                         ‫َر ْق ُم الدعوى‪3498431 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34292038‬تاريخه‪1434/6/6:‬هـ‬\n\n\n      ‫فســخ نــكاح ‪ -‬مطالبــة بفســخ نــكاح للضــرب وشــرب اخلمــر وعــدم‬\n      ‫النفقــة والكراهيــة ‪ -‬تعــذر الصلــح بــن الزوجــن ‪ -‬احلكــم بالفســخ‬\n      ‫مقابــل تنــازل الزوجــة عــن املؤخــر ونفقتهــا ونفقــة األوالد املاضيــة ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول اهلل تعالــى ( ومــن آياتــه أن خلــق لكــم مــن أنفســكم أزواج ـ ًا‬\n                                ‫لتســكنوا إليهــا وجعــل بينكــم مــود ًة ورحمــة )‬\n                           ‫‪ -2‬قوله تعالى ( فال جناح عليهما فيما افتدت به )‬\n                     ‫‪ -2‬قول الرسول صلى اهلل عليه وسلم ( ال ضرر وال ضرار )‬\n      ‫‪ -4‬حديــث امــرأة ثابــت بــن قيــس وافتدائهــا نفســها مــن زوجهــا‬\n                                                                      ‫باحلديقــة ‪.‬‬\n\n\n\n\n      ‫أقامــت زوجــة دعــوى علــى زوجهــا تطالــب فســخ نكاحهــا لســوء عشــرته‬\n      ‫وألنــه يشــرب اخلمــر ويقــوم بضربهــا وال ينفــق عليهــا ‪ ،‬أنكــر املدعــى‬\n      ‫عليــه ضربــه للمدعيــة وعــدم اإلنفــاق عليهــا وشــربه للخمــر ورفــض فســخ‬\n      ‫نكاحهــا ‪ ،‬كتبــت احملكمــة ملكتــب الصلــح لديهــا حملاولــة اإلصــاح‬\n      ‫ـاء علــى قــرار‬\n                   ‫بــن الطرفــن ولكنــه تعـ ّـذر ورأى التفريــق بينهمــا وبنـ ً‬\n      ‫مكتــب الصلــح الــذي رأيــا التفريــق بــن الزوجــن ولقولــه الرســول صلــى‬\n\n‫‪219‬‬\n\f‫اهلل عليــه وســلم ( ال ضــرر وال ضــرار ) وحلديــث امــرأة ثابــت بــن قيــس‬\n‫وافتداءهــا نفســها منــه باحلديقــة ولقولــه تعالــى ( فــا جنــاح عليهمــا فيمــا‬\n‫افتــدت بــه ) حكمــت احملكمــة بفســخ نــكاح املدعيــة مقابــل تنازلهــا‬\n‫عــن مؤخــر صداقهــا ونفقتهــا ونفقــة أوالدهــا املاضيــة و ُأفهمــت بــأن‬\n      ‫عليهــا العــدة الشــرعية ‪ ،‬اعتــرض املدعــى عليــه ‪ ،‬صــدق احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا املــازم القضائــي (‪ )......‬يف احملكمــة‬\n‫العامــة بالريــاض والقائــم بعمــل املكتــب القضائــي رقــم (‪ )21‬وبنــاء‬\n‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n‫برقــم ‪ 3498431‬وتاريــخ ‪1434/02/30‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 34511292‬وتاريــخ ‪1434/2/30‬ه ـ ففــي يــوم الســبت املوافــق‬\n‫‪1434/07/01‬هـ افتتحت اجللسة الساعة ‪ 12 : 30‬وفيها حضرت (‪)......‬‬\n‫أردنيــة اجلنســية مبوجــب رخصــة (‪ )......‬واملعــرف بهــا مــن قبــل والدهــا‬\n‫(‪ )......‬مبوجــب (‪ )......‬وحضــر حلضورهــا وبطلــب إثبــات هويتــه أبــرز‬\n‫رخصــة ســياقة حتمــل صورتــه الشــخصية باســم (‪ )......‬وهــو فلســطيني‬\n‫اجلنســية وبســؤاله عن رخصة اإلقامة قرر أنها يف طور التجديد هكذا‬\n‫قــرر وبســؤال املدعيــة عــن دعواهــا أجابــت قائلــة ‪ :‬إن املدعــى عليــه هــذا‬\n‫احلاضــر هــو زوجــي تزوجنــي يف تاريــخ ‪2005/09/15‬م مبوجــب عقــد‬\n‫النــكاح وولــدت لــه علــى فــراش الزوجيــة كال مــن ‪ ....‬مولــودة يف تاريــخ‬\n‫‪2006/07/17‬م ‪ ....‬مولــود يف تاريــخ ‪2011/02/01‬م وأطلــب فســخ‬\n‫نكاحــي منــه لكونــه يتعــرض لــي يف الفتــرة األخيــرة بزيــادة الضــرب‬\n‫وهــو يشــرب اخلمــر وال ينفــق علــي ولــم أعــد أطيــق العيــش معــه لــذا‬\n\n                                                                                      ‫‪220‬‬\n\f      ‫أرغــب بفســخ نكاحــي منــه هــذه دعــواي وبعرضهــا علــى املدعــى عليــه‬\n      ‫أجــاب قائ ـاً‪ :‬مــا ذكرتــه املدعيــة مــن أنــي زوجهــا وولــدت لــي األوالد‬\n      ‫املذكوريــن يف التواريــخ املذكــورة كلــه صحيــح أمــا مــا ذكرتــه مــن‬\n      ‫كونــي أضربهــا وأشــرب اخلمــر و ال أنفــق عليهــا فغيــر صحيــح وأرفــض‬\n      ‫احلكــم علــي بفســخ نكاحهــا منــي ألنــه ال يوجــد ســبب يدعوهــا إلــى‬\n      ‫فســخ النــكاح هكــذا أجــاب وقــد جــرت الكتابــة إلــى مكتــب الصلــح‬\n      ‫حملاولــة اإلصــاح بــن الطرفــن و االطــاع علــى أســباب النــزاع بينهمــا‬\n      ‫فوردنــا قرارهــم وتاريــخ ‪1434/05/27‬ه ـ واملتضمــن مــا نصــه‪ :‬نفيــد‬\n      ‫فضيلتــه أنــه مت االجتمــاع بالطرفــن ومحاولــة الصلــح بينهمــا وتقريــب‬\n      ‫وجهــات النظــر و إيجــاد احللــول املناســبة وبيــان مغبــة الشــقاق والنــزاع‬\n      ‫واآلثــار املترتبــة علــى الفــراق إال أن الزوجــة طلبــت فســخ نكاحهــا مــن‬\n      ‫زوجهــا وذكــرت بأنهــا ال ترغــب يف العــودة لــه بســبب ســوء عشــرته لهــا‬\n      ‫وضربهــا وعــدم النفقــة عليهــا وإهانتهــا وأنــه يشــرب اخلمــر حتــى يف نهــار‬\n      ‫رمضــان و ينصــب و يحتــال علــى النــاس بأخــذ أموالهــم وهــو ســجني‬\n      ‫بســبب ذلــك و أنــا مســتعدة بالتنــازل عــن املؤخــر ونفقتــي و نفقــة أوالدي‬\n      ‫املاضيــة وأمــا الــزوج فقــال إننــي ال أوافــق علــى طلــب زوجتــي فســخ‬\n      ‫نكاحهــا بســبب أننــي أريدهــا ومســتعد بــأن أعاشــرها باملعــروف وأنفــق‬\n      ‫عليهــا فجــرى مناصحــة الزوجــة وتذكيرهــا بــاهلل تعالــى وبقولــه صلــى‬\n      ‫اهلل عليــه وســلم ( أميــا امــرأة طلبــت الطــاق مــن زوجهــا مــن غيــر مــا‬\n      ‫بــأس فحــرام عليهــا رائحــة اجلنــة ) ولكنهــا أصــرت علــى طلبهــا وظهــر‬\n      ‫لنــا الكــره الشــديد مــن قبــل الزوجــة لزوجهــا ورجوعهــا لزوجهــا وهــي‬\n      ‫علــى هــذا احلــال ال يخــدم احليــاة الزوجيــة ويتنافــى مــع قولــه تعالــى (‬\n      ‫ومــن آياتــه أن خلــق لكــم مــن أنفســكم أزواجــا لتســكنوا إليهــا وجعــل‬\n\n\n‫‪221‬‬\n\f‫بينكــم مــود ًة ورحمــة ) وقولــه صلــى اهلل عليــه وســلم ( ال ضــرر وال‬\n‫ضــرار ) وعليــه فإننــا نــرى التفريــق بينهمــا علــى العــوض الــذي اســتعدت‬\n‫بــه الزوجــة وهــو تنازلهــا عــن النفقــة املاضيــة لهــا وألبنائهــا وكذلــك‬\n‫املؤخــر املذكــور يف عقــد النــكاح هــذا مــا لدينــا وبــاهلل التوفيــق وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬أ‪.‬ه ـ وبعرضــه‬\n‫علــى الطرفــن صادقــا علــى حضورهمــا ومــا ذكــر فيــه ورفــض الــزوج‬\n‫فســخ النــكاح مقابــل التنــازل عــن الصــداق املؤخــر والنفقــة املاضيــة‬\n‫فجــرى نصــح الزوجــة بالعــودة إلــى زوجهــا وذكــر مــا يرغــب يف ذلــك‬\n‫مــن بيــان آثــار الطــاق عليهــا وعلــى أوالدهــا لكنهــا رفضــت رفض ـ ًا‬\n‫قاطع ـ ًا وتلــوت عليــه مــا جــاء مــن الوعيــد يف مــن طلبــت طــاق زوجهــا‬\n‫مــن غيــر مــا بــأس فأصــرت علــى طلبهــا وأن لديهــا الســبب الشــرعي‬\n‫لفســخ نكاحهــا منــه‪ ،‬ثــم جــرى نصــح الــزوج بطــاق زوجتــه وتســريحها‬\n‫بإحســان وأن طالقــه لهــا تفضــل عليهــا فرفــض ذلــك ثــم عرضــت عليــه‬\n‫مــا تقدمــت بــه الزوجــة مــن طلــب مخالعتهــا لــه مقابــل الصــداق املؤخــر‬\n‫والنفقــة املاضيــة فرفــض ذلــك وبســؤال املدعيــة عــن املهــر املقبــوض‬\n‫أجابــت قائلــة ‪ :‬قبضنــا مــن املهــر ثمانيــة آالف ريــال فقــط هكــذا أجــاب‬\n‫وبعرضــه علــى املدعــى عليــه أجــاب قائــا ‪ :‬املهــر املقبــوض خمســة و‬\n‫ـاء‬\n  ‫عشــرون ألــف ريــال و املؤخــر خمســون ألــف ريــال هكــذا أجــاب فبنـ ً‬\n‫علــى مــا تقــدم مــن الدعــوى و اإلجابــة وقــرار مكتــب الصلــح املتضمــن‬\n‫أن رجــوع الزوجــة لزوجهــا ال يخــدم حــال الزوجيــة وال يحقــق مقصودهــا‬\n‫ويتنافــى مــع قولــه تعالــى ( ومــن آياتــه أن خلــق لكــم مــن أنفســكم‬\n‫أزواجـ ًا لتســكنوا إليهــا وجعــل بينكــم مــود ًة ورحمــة ) وقولــه صلــى اهلل‬\n‫عليــه وســلم ( ال ضــرر وال ضــرار ) وملــا جــاء يف الصحيــح مــن قصــة ثابــت‬\n\n\n                                                                                    ‫‪222‬‬\n\f      ‫بــن قيــس وافتــداء زوجتــه نفســها منــه باحلديقــة ولعمــوم قولــه تعالــى (‬\n      ‫فــا جنــاح عليهمــا فيمــا افتــدت بــه ) وملــا تقدمــت بــه الزوجــة مــن التنــازل‬\n      ‫عــن نفقتهــا املاضيــة ومؤخــر صداقهــا لــذا فقــد حكمــت بفســخ نــكاح‬\n      ‫املدعيــة ‪ ......‬مــن زوجهــا ‪ ......‬مقابــل تنازلهــا عــن مؤخــر صداقهــا وقــدره‬\n      ‫خمســون ألــف ريــال ونفقتهــا ونفقــة أوالدهــا املاضيــة وأفهمتهــا أن عليهــا‬\n      ‫العــدة الشــرعية ثــاث حيضــات بعــد أن قــررت أنهــا مــن ذوات األقــراء‬\n      ‫كمــا هــو قــول جمهــور الفقهــاء وأال تتــزوج حتــى يكتســب احلكــم‬\n      ‫القطعيــة وبعــرض احلكــم علــى الطرفــن قــررت املدعيــة القناعــة وقــرر‬\n      ‫املدعــى عليــه املعارضــة وطلــب االســتئناف فســلم صــورة احلكــم لتقــدمي‬\n      ‫اعتراضــه عليــه خــال ثالثــن يومــا مــن تاريخــه فــإن مضــت املــدة ولــم‬\n      ‫يقدمهــا ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                       ‫يف ‪1434/7/1‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫وتاريــخ ‪1434/7/26‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة املــازم‬\n               ‫القضائــي باحملكمــة الشــيخ‪ .............../‬وتاريــخ ‪1434/7/1‬هــ‪.‬‬\n      ‫اخلــاص بدعــوى‪ /‬بشــأن فســخ نــكاح وقــد تضمــن الصــك حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى‬\n      ‫احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه‬\n                                                                                     ‫وســلم ‪.‬‬\n\n\n‫‪223‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":219,"source_page_end":223,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9f158063bab65d19ff8ffdc4ee46a9e35943a511360afc621ad3d28b8de1552c","normalized_text_hash":"5ea2a96ad49588cbdecac541cef9636a2505ee8bda4de331a9513a5f4e50d6d8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p219-34255305"},{"id":"d2f374e4-ea52-5565-9c83-7d36b033585e","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -املطالبة بفسخ نكاح لعدم النفقة والهجر -عدم حضور املدعى عليه (الزوج) رغم التبليغ -شهادة الشاهدين العدول -ميني اإلستظهار -احلكم بفسخ النكاح .","document_number":"33245589","case_number":"32116807","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/12","year":"1434","subject":"فسخ نكاح -املطالبة بفسخ نكاح لعدم النفقة والهجر -عدم حضور املدعى عليه (الزوج) رغم التبليغ -شهادة الشاهدين العدول -ميني اإلستظهار -احلكم بفسخ النكاح .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/5/12 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33245589 :‬‬\n                   ‫َر ْق ُم الدعوى‪32116807 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34233563‬تاريخه‪1434/6/6 :‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬املطالبــة بفســخ نــكاح لعــدم النفقــة والهجــر ‪ -‬عدم حضور‬\n‫املدعــى عليــه (الــزوج) رغــم التبليــغ ‪ -‬شــهادة الشــاهدين العــدول ‪ -‬ميني‬\n                                   ‫اإلســتظهار ‪ -‬احلكم بفســخ النكاح ‪.‬‬\n\n\n\n\n                                ‫‪ -1‬قوله تعالى ( لينفق ذو سعة من سعته )‬\n             ‫‪ -2‬قول اهلل تعالى ( فإمساك مبعروف أو تسريح بإحسان )‬\n‫‪ -3‬قــول الرســول صلــى اهلل عليــه وســلم ( يــا معشــر الشــباب عليكــم‬\n                                                               ‫بالــزواج ‪...‬إلــخ )‬\n              ‫‪ -4‬قول الرسول صلى اهلل عليه وسلم ( ال ضرر وال ضرار )‬\n‫‪ -5‬قــول الرســول صلــى اهلل عليــه وســلم ( امرأتــك تقــول أطعمنــي وإال‬\n                                                                         ‫فارقنــي )‬\n‫‪ -6‬ويف سن ــن ســعيد بــن منصــور عــن ســعيد بــن املســيب يف الرجــل ال‬\n‫يجــد مــا ينفقــه علــى امرأتــه يفــرق بينهمــا إلــخ ‪ ....‬زاد املعــاد ‪512/5‬‬\n‫‪ -7‬قــول البهوتــي (فــإن لــم يعلــم خبــره أي الــزوج أو علــم إذا لــم نــرى يف‬\n                     ‫كالمهــم هــذا القيــد إلــخ ‪ )...‬كشــاف القنــاع ‪480/5‬‬\n                                              ‫‪ -8‬قاعدة ( ال ضرر وال ضرار )‬\n                              ‫‪ -9‬املادة ‪ 1/55‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n                                                                                      ‫‪224‬‬\n\f      ‫أقامــت زوجــة دعــوى علــى زوجهــا املتغيــب عــن مجلــس احلكــم وذلــك‬\n      ‫لتركــه لهــا وابنهــا منــه مــدة تزيــد عــن أربــع ســنوات ولــم ينفــق عليهــم‬\n      ‫خــال تلــك املــدة ‪ -‬لــم يحضــر املدعــى عليــه مع تبلغه لشــخصه ‪ ،‬فقررت‬\n      ‫احملكمــة مواصلــة ســماع الدعــوى غيابي ـ ًا فطلبــت مــن املدعيــة البينــة‬\n      ‫فأحضــرت شــاهدين مــن أقاربهمــا وشــهدا بصحــة دعــوى املدعيــة مــن‬\n      ‫أن املدعــى عليــه تركهــا مــدة طويلــه وعــدل الشــاهدان ‪ ،‬كمــا أبــرزت‬\n      ‫املدعيــة صــورة عقــد نكاحهــا للمدعــى عليــه فوجهــت لهــا احملكمــة‬\n      ‫ميــن االســتظهار بــأن زوجهــا املدعــى عليــه ال يحضــر إليهــا وال ينفــق‬\n      ‫عليهــا وال علــى ولدهــا واســتعدت بذلــك وحلفــت‪ ،‬ولشــهادة الشــاهدين‬\n      ‫املثبتــن لغيــاب املدعــى عليــه ولليمــن التــي أدتهــا املدعيــة ولقولــه‬\n      ‫تعالــى (لينفــق ذو ســعة مــن ســعته) وحديــث (امرأتــك تقــول أطعمنــي‬\n      ‫أو فارقنــي) ولقاعــدة ال ضــرر وال ضــرار وألنــه يتعــذر مقصــود النــكاح‬\n      ‫للغيبــة فســخت احملكمــة نــكاح املدعيــة مــن عصمــة املدعــى عليــه‬\n      ‫وحكمــت بــه وأفهمتهــا بــأن عليهــا العــدة الشــرعية وقــررت احملكمــة‬\n      ‫ـاء علــى املــادة ‪ 1/55‬مــن‬\n                                 ‫أن هــذا احلكــم علــى املدعــى عليــه حضــوري بنـ ً‬\n                                     ‫نظــام املرافعــات الشــرعية ‪ -‬صــدق احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).......‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس وتاريــخ‬\n      ‫‪1432/04/09‬ه ـ يف يــوم األربعــاء املوافق‪1432/07/27‬ه ـ فتحــت‬\n\n‫‪225‬‬\n\f‫اجللســة للنظــر يف دعــوى ضــد زوجهــا وفيهــا حضــرت ســعودية واملعــرف‬\n‫بهــا مــن قبــل أخيهــا ســعودي ولــم يحضــر املدعــى عليــه ســعودي ولــم‬\n‫يردنــا مــا يفيــد تبلغــه منعدمــه ويف يــوم االثنــن املوافــق ‪1433/02/08‬‬\n‫ه ـ فتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــرت املدعيــة يرافقهــا‬\n‫شــقيقها املذكــور اســمه ورقــم هويتــه ســلفا ولــم يحضــر املدعــى عليــه‬\n‫وال وكيــل عنــه رغــم تبلغــه لشــخصه حســب إفــادة محضــر اخلصــوم‬\n‫باحملكمــة املرفقــة باملعاملــة وحيــث احلــال مــا ذكــر فقــد أذنــت يف‬\n‫ســماع الدعــوى ضــده غيابيــا وبســؤال املدعيــة عــن دعواهــا قالــت إن‬\n‫املدعــى عليــه زوجــي عقــد علــي بتاريــخ ‪1428/1/21‬ه ـ علــى مهــر قــدره‬\n‫خمســون ألــف ريــال وبعــد زواجــي بشــهر تركنــي عنــد أهلــي وأنــا حامــل‬\n‫منــه وأجنبــت منــه ولــدا ‪ ......‬يبلــغ مــن العمــر أربــع ســنوات ومــن ذلــك‬\n‫التاريــخ وحتــى اآلن لــم يســأل عنــي وال علــى ولــده ولــم يصــرف علينــا ولــم‬\n‫يســم ولــده إال بشــكوى مــن املستشــفى أطلــب احلكــم بفســخ نكاحــي‬\n‫منــه هــذه دعــواي وبســؤالها البينــة علــى دعواهــا طلبــت املهلــة فأجيبــت‬\n‫لطلبهــا ويف جلســة أخــرى أحضــرت املدعيــة كال مــن ســعودي بالســجل‬\n‫املدني رقم و ســعودي بالســجل املدني رقم فشــهدا كل واحد على حدة‬\n‫قائــا أشــهد هلل تعالــى بــأن املدعــى عليــه تــزوج باملدعيــة هــذه احلاضــرة‬\n‫وبعــد دخولــه بهــا ســافرت معــه إلــى الدمــام شــهرا وبعــد رجوعهمــا لــم تره‬\n‫ولــم يرجــع إليهــا وحملــت منــه وأجنبــت ولــدا ذكــرا اســمه ‪ ......‬وبعدمــا‬\n‫علــم بوالدتهــا جــاء لبيــت أهلهــا ليــرى ابنــه بعــد رؤيتــه لــه غــادر مــرة‬\n‫أخــرى حتــى اســتدعي عــن طريــق مرجعــه احلــرس الوطنــي لتســمية الولــد‬\n‫ولعالجــه ولــم يحضــر بهــذا االســتدعاء ولــم يرجــع إلــى زوجتــه وولــده ولــم‬\n‫ينفــق عليهمــا حتــى اآلن هكــذا شــهدا وجــرى ســؤال الشــاهدين هــل‬\n\n\n                                                                                      ‫‪226‬‬\n\f      ‫لهمــا قرابــة بالزوجــن قــال األول أننــي زوج أخــت املدعيــة وقــال الثانــي‬\n      ‫أننــي ابــن أخــت املدعيــة وقــد عــدال مــن قبــل ســعودي بالســجل املدنــي‬\n      ‫رقــم ســعودي فســألت املدعيــة عــن عقــد النــكاح أبــرزت صــورة منه وهو‬\n      ‫صــادر مــن احملكمــة اجلزئيــة للضمــان واألنكحــة بالريــاض برقــم ‪521‬‬\n      ‫وتاريــخ ‪1428 /1/21‬ه ـ يتضمــن عقــد نــكاح املدعــى عليــه ‪ .........‬علــى‬\n      ‫املدعيــة ‪ .........‬علــى مهــر قــدره خمســون ألــف ريــال فأفهمــت املدعيــة‬\n      ‫بتوجــه ميــن االســتظهار عليهــا بــأن زوجهــا املدعــى عليــه ال يحضــر إليهــا‬\n      ‫وال ينفــق عليهــا وال علــى ولدهــا فاســتعدت لذلــك بعــد أن بينــت لهــا‬\n      ‫عظــم اليمــن وخطرهــا وحلفــت قائلــة واهلل العظيــم الــذي ال إلــه إال هــو‬\n      ‫إن زوجــي املدعــى عليــه لــم ينفــق علــي وعلــى ولــدي منــذ تركنــا ولــم‬\n      ‫ـاء علــى مــا تقدم‬ ‫يحضــر إلينــا ولــم نــره واهلل العظيــم هكــذا حلفــت‪ ،‬فبنـ ً‬\n      ‫مــن دعــوى املدعيــة ومــن اإلجــراءات املضبوطــة ســلفا والتــي تفيــد تبلــغ‬\n      ‫املدعــى عليــه لشــخصه واســتناد ًا لألســباب التاليــة ‪ -1:‬البينــة الشــرعية‬\n      ‫املتمثلــة يف شــهادة الشــاهدين املعدلــن التــي تفيــد بغيــاب املدعــي عــن‬\n      ‫زوجتــه املدعيــة وابنهــا منــه وعــدم اإلنفــاق عليهمــا منــذ غيابــه قبل خمس‬\n      ‫ســنوات والشــاهدان قريبــان للمدعيــة كمــا هــو موضــح ســلفا‪ -2 ،‬ميــن‬\n      ‫االســتظهار مــن املدعيــة وفــق دعواهــا حســبما ذكــر ســلفا ألن احلكــم‬\n      ‫حكــم علــى غائــب وهنــا كبعــض األمــور التــي ذكرتهــا املدعيــة مــا ال‬\n      ‫يعلمــه مــن البشــر أحــد إال هــي‪ -3 ،‬أن نصــوص الشــريعة الغـ ّـراء دلــت‬\n      ‫علــى أن النفقــة واجبــة للزوجــة كمــا يف قولــه تعالــى (لينفــق ذو ســعة‬\n      ‫مــن ســعته) ويف ســن النســائي (امرأتــك تقــول أطعمنــي وإال فارقنــي )‬\n      ‫ويف ســن ســعيد بــن منصــور عــن ســعيد بــن املســيب يف الرجــل ال يجــد‬\n      ‫مــا ينفقــه علــى امرأتــه يفــرق بينهمــا قــال نعــم قلــت ســنة قــال ســنة قــال‬\n\n\n‫‪227‬‬\n\f‫ابــن القيــم يف زاد املعــاد ه‪ ( 512/‬وهــذا ينصــرف إلــى ســنة رســول اهلل‬\n‫صلــى اهلل عليــه وســلم) أ ‪.‬ه ـ فكيــف مــن تغيــب وامتنــع امتناعـ ًا حقيقيـ ًا‬\n‫وحكميـ ًا عــن النفقــة ومــن تدبــر مقاصــد الشــرع وعدلــه وحكمتــه ومــا‬\n‫اشــتمل عليــه مــن املصالــح ودفــع املفاســد علــم أن تــرك الزوجــة لهــذه‬\n‫املــدة بــدون نفقــة ســبب موجــب للفســخ قــال يف كشــاف القنــاع ‪480/5‬‬\n‫( فــإن لــم يعلــم خبــره أي الــزوج أو علــم إذ لــم نــر يف كالمهــم هــذا القيــد‬\n‫وتعــذرت النفقــة كمــا تقــدم باالســتدانة وعــدم الوصــول إلــى شــيء‬\n‫مــن مالــه فلهــا الفســخ ألنهــا لــم تقــدر علــى الوصــول إلــى نفقتهــا أشــبه‬\n‫مــا لوثبــت إعســاره ) أ ‪.‬ه ـ ومثلــه يف منتهــى اإلرادات ‪ -4 ، 378/2‬أن‬\n‫الراجــح مــن أقــوال أهــل العلــم انــه يفــرق بــن املــرأة وزوجهــا املتغيــب إذا‬\n‫ا عمــا إذا‬  ‫تضــررت بتغيبــه ولــو تركلهــا مــا حتتــاج إليــه مــن نفقــة فض ـ ً‬\n‫لــم يتــرك لهــا شــيئ ًا وهــذا هــو رأي اإلمامــن مالــك وأحمــد رحمهمــا اهلل‬\n‫تعالــى ‪ -5‬بقــاء الزوجــة بهــذه احلالــة يف عصمــة الغائــب عنهــا فيــه ضــرر‬\n‫عليهــا وتعريــض لهــا للفتنــة ومضــارة بهــا ومــن القواعــد الفقهيــة الكليــة‬\n‫اخلمــس قاعــدة (ال ضــرر وال ضــرار) التــي مســتندها قــول النبــي صلــى‬\n‫اهلل عليــه وســلم يف احلديــث الصحيــح ‪( :‬ال ضــرر وال ضــرار )‪ -6 ،‬تــرك‬\n‫املدعيــة مــن قبــل زوجهــا املدعــى عليــه مــدة خمــس ســنوات مــن تاريــخ‬\n‫غيابــه علــى هــذا الوضــع ليــس مــن اإلمســاك باملعــروف ومــن املعلــوم أنــه‬\n‫إذا فــات اإلمســاك باملعــروف وجــب التســريح باإلحســان لقولــه تعالــى ‪:‬‬\n‫( فإمســاك مبعــروف أو تســريح بإحســان ) وكالهمــا معــدوم مــن قبــل‬\n‫املدعــي عليــه فوجــب الفســخ ‪ -7‬أعظــم املقاصــد الشــرعية التــي شــرع‬\n‫لهــا النــكاح هــو اســتمتاع الزوجــة بزوجهــا قــال صلــى اهلل عليــه وســلم‬\n‫يف احلديــث الصحيــح ‪ ( :‬يــا معشــر الشــباب عليكــم بالــزواج فإنــه أغــض‬\n\n\n                                                                                        ‫‪228‬‬\n\f      ‫للبصــر وأحصــن للفــرج ) احلديــث وعنــد غيــاب الــزوج املدعــى عليــه لهــذه‬\n      ‫املــدة الطويلــة ينعــدم هــذا املقصــود وحينئــذ يكــون ذلــك ســببا للفســخ‬\n      ‫الســيما املدعــى عليــه يف هــذه املــدة الطويلــة ال يعــذر بتركــه أهلــه‬\n      ‫إلمكانــه االتصــال بهــم ومواصلتهــم خاصــة يف هــذا العصــر لــو كان‬\n      ‫راغبـ ًا يف اإلمســاك أو املعاشــرة احلســنة مــن أجــل تلــك األســباب مجتمعــة‬\n      ‫فقــد فســخت نــكاح املدعيــة مــن عصمــة زوجهــا املدعــى عليــه وبــه‬\n      ‫حكمــت وأفهمــت املدعيــة أن عليهــا عــدة الفســخ ثــاث حيــض كمــا‬\n      ‫هــو مذهــب اجلمهــور حيــث ذكــرت أنهــا مــا زالــت حتيــض وهــذه العــدة‬\n      ‫تبــدأ مــن تاريــخ احلكــم وبعــد اكتســابه صفــة التصديــق مــن محكمــة‬\n      ‫االســتئناف وبــه تصبــح بائن ـ ًا مــن زوجهــا بينونــة صغــرى ال حتــل لــه إال‬\n      ‫بعقــد تتوفــر فيــه شــروط الصحــة الشــرعية كمــا أفهمتهــا أال تتــزوج‬\n      ‫إال بعــد تصديــق احلكــم مــن محكمــة االســتئناف وبعــد انقضــاء العــدة‬\n      ‫الشــرعية وبعــرض احلكــم علــى املدعيــة قنعــت بــه ويكــون هــذا احلكــم‬\n      ‫يف حــق املدعــى عليــه حضوريــا طبقــا للمــادة ‪ 1/55‬مــن نظــام املرافعــات‬\n      ‫الشــرعية وســوف يبلــغ بنســخة منــه لالعتــراض عليــه مــن عدمــه حســب‬\n      ‫التعليمــات وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/5/12‬هــ‪.‬‬\n      ‫احلمد هلل وحده وبعد فلدي أنا د‪ .‬القاضي يف احملكمة العامة بالرياض‬\n      ‫واخللــف لفضيلــة الشــيخ ففــي يــوم اإلثنــن املوافــق ‪1434/05/20‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 08 : 15‬بنــاء علــى اإلحالــة الــواردة إلينــا مــن‬\n      ‫فضيلــة الرئيــس املســاعد يف ‪1434/5/4‬ه ـ املرفــق بهــا قــرار املالحظــة‬\n      ‫الصــادرة مــن دائــرة األحــوال الشــخصية األولــى يف ‪1434/04/22‬ه ـ‬\n      ‫ونــص احلاجــة منــه ‪ ( :‬وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي‬\n\n\n‫‪229‬‬\n\f‫واحلقــه علــى الصــك بنــاء علــى قرارنــا وتاريــخ ‪1433/12/20‬ه ـ لوحــظ‬\n‫ان مــا احلقــه حاكــم القضيــة علــى الصــك بتاريــخ ‪1434/2/23‬ه ـ لــم‬\n‫يلحــق علــى الضبــط وصورتــه وســجل الصــك والبــد مــن ذلــك فعلــى‬\n‫فضيلــة خلفــه إكمــال الــازم حيــال ذلــك ومــن ثــم إعــادة املعاملــة إلــى‬\n‫محكمــة االســتئناف إلكمــال الزمهــا واهلل املوفــق) ‪ .‬وبالرجــوع إلــى‬\n‫اإلحلــاق املذكــور وجــد نصــه ‪ ( :‬احلمــد هلل وحــده وبعــد فقــد عــادت‬\n‫املعاملــة مــن احملكمــة العامــة بالريــاض وتاريــخ ‪1434/02/05‬ه ـ‬\n‫املقيــدة مبحكمــة اســتئناف تبــوك وتاريــخ ‪1434/02/12‬ه ـ املتعلقــة‬\n‫بدعــوى مرفقــا بهــا قــرار محكمــة االســتئناف يف ‪1433/12/20‬ه ـ‬\n‫املتضمــن بعــث املعاملــة لــي يف مقــر عملــي احلالــي محكمــة االســتئناف‬\n‫لإلجابــة علــى امللحوظتــن الواردتــن يف قــرار اســتئناف الريــاض‬\n‫املرفــق رقــم ‪ 33420384‬وتاريــخ ‪1433/10/09‬ه ـ املتضمــن ملحوظتــي‬\n‫أصحــاب الفضيلــة باألكثريــة وهمــا أوال ‪ -:‬لــم أذكــر يف احلكــم هــل‬\n‫الفســخ علــى عــوض أو بــدون عــوض ‪ .‬ثانيــا ‪ -:‬ظهــر مــن أوراق املعاملــة‬\n‫أن املدعــى عليــه تبلــغ باحلكــم مبوجــب إشــعار التبليــغ املرفــق واملوقــع‬\n‫مــن قبلــه ‪ ،‬ولــم يــدون بالصــك وال صــورة ضبطــه هــل تقــدم بالئحــة‬\n‫اعتــراض أو ال‪ ،‬وإذا لــم يكــن تقــدم بالئحــة مــع تبلغــه باحلكــم فمــا‬\n‫وجــه رفعــه حملكمــة االســتئناف‪ ،‬انتهــى وبنــاء علــى ذلــك جــرى تأمــل‬\n‫هاتــن املالحظتــن وأجيــب عــن األولــى بــأن الفســخ علــى غيــر عــوض‪،‬‬\n‫ألنــه أوقــع لســببني االنفــاق عليهــا ‪ ،‬وأمــا املالحظــة الثانيــة فإنــه جــرى‬\n‫مخاطبــة مرجــع املدعــى عليــه احلــرس الوطنــي إلبالغــه بنســخة احلكــم‬\n‫حســب إجــراءات التبليــغ ‪ ،‬وذلــك مبوجــب اخلطــاب رقــم ‪33713744‬‬\n‫وتاريــخ ‪1433/04/14‬ه ـ املرفــق باملعاملــة علــى اللفــه رقــم ‪ 7‬وكان‬\n\n\n                                                                                      ‫‪230‬‬\n\f      ‫ذلــك قبــل انتقالــي إلــى محكمــة اســتئناف تبــوك‪ ،‬ثــم تبلــغ باحلكــم‬\n      ‫لشــخصه يف تاريــخ ‪1433/5/29‬ه ـ وقــد ورد اجلــواب بعــد مغادرتــي‬\n      ‫احملكمــة لالنتقــال إلــى محكمــة االســتئناف بتبــوك وذلــك بتاريــخ‬\n      ‫‪1433/06/11‬ه ـ ولــذا فإنــي ال زلــت علــى مــا حكمــت بــه وأمــرت‬\n      ‫بالصــك وبعثــه إلــى احملكمــة العامــة بالريــاض إلحلــاق ذلــك بالضبــط‬\n      ‫وســجله ‪ ،‬وبــاهلل التوفيــق ) ‪ .‬وللبيــان جــرى حتريــره وأمــرت بإعــادة‬\n      ‫املعاملــة حملكمــة االســتئناف املوقــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/20‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/06/21‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 09 : 50‬هــذا وقــد عــادت املعاملــة مــن‬\n      ‫محكمــة االســتئناف وتاريــخ ‪1434/6/13‬ه املرفــق بهــا قــرار التصديــق‬\n      ‫الصــادر مــن دائــرة األحــوال الشــخصية األولــى وتاريــخ ‪1434/06/06‬ه ـ‬\n      ‫ونــص احلاجــة منــه بعــد املقدمــة ‪( :‬وحيــث ســبق دارســة الصــك وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي‬\n      ‫وأحلقــه علــى الصــك وصــورة ضبطــه بتاريــخ ‪1434/05/20‬ه ـ بنــاء علــى‬\n      ‫قرارانــا رقــم ‪ 34195321‬وتاريــخ ‪1434/04/22‬ه ـ لــم يظهــر مــا يوجــب‬\n      ‫االعتــراض واهلل املوفــق)‪ .‬وقــد همــش مبضمونــه علــى ظهــر الصــك‬\n      ‫وأمــرت بنقــل ذلــك يف ضبطــه وســجله وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n      ‫لتمييــز قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة املســاعد‬\n      ‫وتاريــخ ‪1434/5/21‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n\n\n‫‪231‬‬\n\f‫باحملكمــة ســابق ًا الشــيخ‪ /‬وتاريــخ ‪1433/5/12‬ه ـ اخلــاص بدعــوى‪/‬‬\n‫بشــأن طلــب املدعيــة فســخ نكاحهــا مــن املدعــى عليــه ‪ ،‬وقــد تضمــن‬\n‫الصــك أن فضيلتــه فســخ نــكاح املدعيــة مــن املدعــى عليــه وبــه حكــم ‪.‬‬\n‫وحيــث ســبقت دراســة الصــك وصــورة ضبطــه وأوراق املعاملــة وباالطالع‬\n‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه علــى الصــك وصــورة ضبطــه‬\n‫بتاريــخ ‪1434/5/20‬ه ـ بنــاء علــى قرارنــا وتاريــخ ‪1434/4/22‬ه ـ لــم‬\n‫يظهــر مــا يوجــب االعتــراض‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                       ‫وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪232‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":224,"source_page_end":232,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"89754570ff7199379db6dcdef7b4b7e07f0e3c73f590ec4a39252f75bfa51def","normalized_text_hash":"03f101924d172bf2397b55cbc7049966caefefe41db80952686d973fda09a3d0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p224-33245589"},{"id":"f0d80fa7-a4bb-5ea5-a96f-71ba8a3670f8","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول لعدم النفقة -شهادة الشهود ومين املدعية -االمتناع عن النفقة أحد موجبات فسخ النكاح -احلكم غيابي ا بفسخ النكاح -الغائب على حجته","document_number":"3441536","case_number":"32155281","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املتضمن عقد نكاحها على مهر خمسة وعشرين ألف ريال ولم تشترط عليه شيئا","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/19","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول لعدم النفقة -شهادة الشهود ومين املدعية -االمتناع عن النفقة أحد موجبات فسخ النكاح -احلكم غيابي ا بفسخ النكاح -الغائب على حجته","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/2/19 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3441536 :‬‬\n                         ‫َر ْق ُم الدعوى‪32155281 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34223987‬تاريخه‪1434/5/27 :‬هـ‬\n\n\n      ‫فســخ نــكاح ‪ -‬طلــب الزوجــة فســخ النــكاح بعــد الدخــول لعــدم النفقــة‬\n      ‫‪ -‬شــهادة الشــهود وميــن املدعيــة ‪ -‬االمتنــاع عــن النفقــة أحــد موجبــات‬\n      ‫فســخ النــكاح ‪ -‬احلكــم غيابي ـ ًا بفســخ النــكاح ‪ -‬الغائــب علــى حجتــه‬\n                                                                    ‫متــى حضــر ‪.‬‬\n\n\n\n\n      ‫‪ .1‬االمتنــاع عــن النفقــة أحــد موجبــات الفســخ‪ ،‬قــال يف الكشــاف (وهــذا‬\n      ‫قــول عمــر وعلــي وأبــو هريــرة لقولــه تعالــى‪( :‬فإمســاك مبعــروف أو‬\n      ‫تســريح بإحســان) [البقــرة ‪ ]229:‬وليــس اإلمســاك مــع تــرك اإلنفــاق‬\n      ‫إمســاك ًا مبعــروف فتعــن التســريح وقــال صلــى اهلل عليــه وســلم‬\n      ‫«امرأتــك تقــول أطعمنــي وإال فارقنــي» رواه أحمــد والــدار قطنــي‬\n      ‫والبيهقــي بإســناد صحيــح ورواه الشــيخان مــن قــول أبــي هريــرة وروى‬\n      ‫الشــافعي وســعيد بــن ســفيان عــن أبــي الزنــاد قــال ‪»:‬ســألت ســعيد‬\n      ‫بــن املســيب عــن الرجــل ال يجــد مــا ينفــق علــى امرأتــه ؟ قــال ‪ :‬يفــرق‬\n      ‫بينهمــا قــال أبــو الزنــاد لســعيد ‪ :‬ســنة ؟ قــال ســعيد ســنة» وألن هــذا‬\n      ‫أولــى بالفســخ مــن العجــز بالــوطء وكان علــى التراخــي ألنــه كخيــار‬\n      ‫العيــب»‪ »560/5‬وقــال أيض ـ ًا يف الكشــاف يف موضــع آخــر (فــإن تعــذر‬\n      ‫ذلــك اإلنفــاق عليهــا بــأن لــم يكــن نقــد ًا وال عرض ـ ًا وال عقــار ًا فلهــا‬\n      ‫الفســخ لتعــذر اإلنفــاق عليهــا مــن مالــه كحــال اإلعســار بــل هــذا أولــى‬\n      ‫بالفســخ ولــو فســخ احلاكــم نــكاح الزوجــة لفقــد مــال زوجهــا الغائــب‬\n‫‪233‬‬\n\f‫ينفــق منــه ثــم تبــن لــه مــال ‪ .‬قــال ابــن نصــر اهلل يف حواشــي القواعــد‬\n‫الفقهيــة ‪:‬الظاهــر صحــة الفســخ وعــدم نقضــه ألن نفقتهــا إمنــا تتعلــق‬\n‫مبــا يقــدر عليــه مــن مــال زوجهــا وأمــا مــا كان غائبـ ًا عنهــا ال علــم لهــا‬\n                                      ‫بــه فــا تكلــف الصبــر الحتمالــه»‪»5/563‬‬\n‫‪ .2‬قــال يف اإلنصــاف قولــه‪« :‬وإن غــاب ولــم يتــرك لهــا نفقــة ولــم تقــدر‬\n‫لــه علــى مــال وال االســتدانة عليــه ‪:‬فلهــا الفســخ» هــذا املذهــب ‪ .‬جــزم بــه‬\n‫يف الوجيــز والنظــم ومنتخــب اآلدمــي وتذكــرة ابــن عبــدوس وغيرهــم‬\n                                 ‫وقدمــه يف املغنــي والشــرح والفــروع وغيرهــم ‪.‬‬\n                             ‫كتاب النفقات ( ‪ )1638 /2‬طبعة بيت األفكار ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة أن املدعــى عليــه تزوجهــا علــى مهــر خمســة وعشــرين‬\n‫ألــف ريــال اســتلمته كامــا ودخــل بهــا يف منــزل أهلهــا ولــم حتمــل منــه‪،‬‬\n‫وأنــه قبــض عليــه بقضيــة (تزويــر إقامــة) مكــث ألجلهــا ســتة أشــهر‬\n‫يف الســجن ‪ ،‬ثــم جــرى ترحيلــه بعــد منعــه مــن الدخــول إلــى اململكــة‪،‬‬\n‫وأنهــا ال تعلــم لــه محــل إقامــة يف بلــده ميكنهــا التواصــل معــه ‪ ،‬وأنــه مــن‬\n‫زواجهــا بــه لــم ينفــق عليهــا ولــم يتــرك لهــا نفقــة وطلبــت فســخ نكاحهــا؛‬\n‫لتضررهــا مــن بقائهــا معلقــة ‪ ،‬متــت الكتابــة لــإدارة العامــة للجــوازات‬\n‫فــورد اجلــواب املتضمــن أن املدعــى عليــه غــادر اململكــة بتأشــيرة خــروج‬\n‫نهائــي ‪ ،‬مت طلــب البينــة مــن املدعيــة علــى دعواهــا ‪ ،‬أبــرزت املدعيــة‬\n‫صــورة مــن الصــك الصــادر مــن احملكمــة العامــة باملدينــة املتضمــن‬\n‫عقــد نكاحهــا علــى مهــر خمســة وعشــرين ألــف ريــال ولــم تشــترط‬\n‫عليــه شــيئا ‪ ،‬أحضــرت شــاهدين ‪ ،‬ومت ســماع شــهادتهما‪ ،‬وتعديلهمــا‬\n\n                                                                                        ‫‪234‬‬\n\f      ‫‪ ،‬بطلــب ميــن االســتظهار مــن املدعيــة علــى دعواهــا حلفتهــا ‪ ،‬األصــل‬\n      ‫عــدم اإلنفــاق‪ ،‬يعضــده ويؤيــده خطــاب اجلــوازات ‪ ،‬وشــهادة الشــاهدين‬\n      ‫املعدلــن شــرعاً‪ ،‬وميــن االســتظهار مــن املدعيــة ‪ ،‬االمتنــاع عــن النفقــة‬\n      ‫أحــد موجبــات الفســخ ‪ ،‬لــذا مت احلكــم بفســخ نــكاح املدعيــة مــن‬\n      ‫زوجهــا املدعــى عليــه‪ ،‬وجــرى إفهــام املدعيــة أنهــا بانــت مــن املدعــى عليــه‬\n      ‫بينونــة صغــرى ال حتــل لــه إال بعقــد جديــد مســتوف أركانــه وشــروطه‪،‬‬\n      ‫وأن عليهــا العــدة الشــرعية وأن ال تتــزوج إال بعــد خروجهــا مــن العــدة ‪،‬‬\n                  ‫بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).......‬القاضــي يف احملكمــة‬\n      ‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32155281‬وتاريــخ‬\n      ‫‪ 1432/05/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32489566‬وتاريــخ‬\n      ‫‪ 1432/05/02‬ه ـ ففــي يــوم الثالثــاء ‪ 1434/02/05‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 11 : 30‬وفيهــا حضــرت (‪ ).......‬ميامنــار اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ).......‬ادعــت قائلــة إن املدعى عليــه (‪).......‬‬\n      ‫بنجالديشــي اجلنســية وأصلــه برمــاوي عقــد علــي يف ‪1413/1/13‬ه ـ‬\n      ‫علــى مهــر خمســة وعشــرين ألــف ريــال اســتلمته كامــا وقــد دخــل‬\n      ‫بــي يف منــزل أهلــي إال أنــي لــم أحمــل منــه وقــد قبــض عليــه بقضيــة‬\n      ‫تزويــر إقامــة مكــث ألجلهــا ســتة أشــهر يف الســجن ثــم جــرى ترحيلــه‬\n      ‫يف ‪1432/6/5‬ه ـ بعــد منعــه مــن الدخــول يف اململكــة ال أعلــم لــه محــل‬\n      ‫إقامــة يف بلــده ميكننــي التواصــل معــه وهــو مــن زواجــي بــه لــم ينفــق‬\n\n‫‪235‬‬\n\f‫عليــه ولــم يتــرك لــي نفقــة حتــى اليــوم لــذا ولتضــرري ببقائــي معلقــة لــذا‬\n‫فإنــي أطلــب فســخ نكاحــي منــه وكنــا قــد كتبنــا جلــوازات العاصمــة‬\n‫لطلــب اإلفــادة فعــاد اجلــواب بالكتــاب رقــم ‪ 8840‬يف ‪1433/10/17‬ه ـ‬\n‫املتضمــن بأنــه بــأن املدعــى عليــه غــادر اململكــة يف ‪1432/6/5‬ه ـ‬\n‫بتأشــيرة خــروج نهائــي رقــم ‪ 78872883‬صــادرة مــن مكتــب حتقيــق‬\n‫ســجناء املدينــة أ‪.‬ه ـ فطلبــت منهــا البينــة علــى دعواهــا فأبــرزت صــورة‬\n‫مــن الصــك الصــادر مــن احملكمــة العامــة باملدينــة برقــم ‪ ........‬يف‬\n‫‪1431/1/13‬ه ـ واملتضمــن عقــد نكاحهــا عليــه علــى مهــر خمســة‬\n‫وعشــرين ألــف ريــال ولــم تشــترط عليــه شــيئا واملهمــش عليــه يف صفحــة‬\n‫أخــرى برجــوع فضيلــة مصــدره عــن توثيــق العقــد لكــون الــزوج ال يحمــل‬\n‫إقامــة نظاميــة ســارية املفعــول بعــد ثبــت لديــه بأنــه يحمــل إقامــة ســارية‬\n‫املفعــول أ‪.‬ه ـ كمــا أحضــرت للشــهادة ‪ ............‬ميامنــاري اجلنســية املولــود‬\n‫يف ‪1406/1/1‬ه ـ ويعمــل ســائقا حتــت كفالــة ‪ ...........‬حســب رخصــة‬\n‫االقامــة الصــادرة مــن مكــة برقــم …………بأنــه شــقيق املدعيــة‬\n‫و‪ ...........‬مينمــاري اجلنســية واملولــود يف ‪1993/1/1‬م ويعمــل ســائقا‬\n‫لــدى ‪ .........‬حســب رخصــة االقامــة الصــادرة مــن الريــاض برقــم ‪............‬‬\n‫وبعدمــا قــرر بأنــه ال تربطــه صلــة قرابــة بأحــد املتداعيــن وأنــه كان‬\n‫صديقــا للمدعــى عليــه ومــن جماعتــه وعمــل بجــوار محلــه خمس ســنوات‬\n‫تقريبــا شــهد كل واحــد منهمــا منفــردا قائــا أشــهد بــاهلل تعالــى بــأن‬\n‫املدعــى عليــه ‪ ..........‬بنجالديشــي اجلنســية وأصلــه برمــاوي قــد جــرى‬\n‫ترحيلــه قبــل ســنة ونصــف تقريبــا وأنــه ال يعلــم لــه عنــوان يف البلــد الــذي‬\n‫رحــل إليــه وأنــه لــم يتــرك للمدعيــة نفقــة وأنــه ال يبعــث لهــا بنفقــة وأنهــا‬\n‫ال زالــت معلقــة يف ذمتــه هكــذا شــهدا فســألتهما كيــف عرفــا حــال‬\n\n\n                                                                                          ‫‪236‬‬\n\f      ‫املدعــي فأجــاب األول بأنــه كان جــار وعــدال مــن قبــل ‪ .........‬مينمــاري‬\n      ‫اجلنســية حســب رخصــة اإلقامــة الصــادرة مــن مكــة برقــم ‪.........‬‬\n      ‫و‪ ..........‬حســب رخصــة اإلقامــة الصــادرة مــن الريــاض برقــم‪ ..........‬ويف‬\n      ‫يــوم االثنــن ‪1434/2/11‬ه ـ فتحــت اجللســة وفيهــا حضــرت املدعيــة‬\n      ‫بصحبــة والدهــا وبســؤالها إن كان لديهــا زيــادة بينــة فقــررت قائلــة‬\n      ‫ال أمتكــن مــن إحضــار ســوى مــا قدمتــه حــا ًال أ‪.‬ه ـ فطلبــت منهــا ميــن‬\n      ‫االســتظهار علــى دعواهــا فحلفــت قائلــة واهلل العظيــم بــأن املدعــى عليــه‬\n      ‫‪ ..........‬بنجالديشــي اجلنســية وأصلــه برمــاوي قــد جــرى ترحيلــه قبــل‬\n      ‫ســنة ونصــف تقريبــا وأنــه ال يبعــث لــي بنفقــة وتركنــي معلقــة حتــى‬\n      ‫اآلن ويتعــذر علــي االســتدانة عليــه وال أعلــم لــه عنوانـ ًا يف اخلــارج هكــذا‬\n      ‫حلفــت وبعــد قفــل بــاب املرافعــة وبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة‬\n      ‫وألن األصــل عــدم اإلنفــاق يعضــده ويؤيــده خطــاب اجلــوازات وشــهادة‬\n      ‫الشــاهدين املعدلــن شــرع ًا وعلــى ميــن االســتظهار وألن االمتنــاع عــن‬\n      ‫النفقــة أحــد موجبــات الفســخ قــال يف الكشــاف (وهــذا قــول عمــر‬\n      ‫وعلــي وأبــي هريــرة لقولــه تعالــى ‪ ( :‬فإمســاك مبعــروف أو تســريح‬\n      ‫بإحســان ) [البقــرة ‪ ]229:‬وليــس اإلمســاك مــع تــرك اإلنفــاق إمســاك ًا‬\n      ‫مبعــروف فتعــن التســريح وقــال صلــى اهلل عليــه وســلم «امرأتــك تقــول‬\n      ‫أطعمنــي وإال فارقنــي» رواه أحمــد والدارقطنــي والبيهقــي بإســناد‬\n      ‫صحيــح ورواه الشــيخان مــن قــول أبــي هريــرة وروى الشــافعي وســعيد‬\n      ‫بــن ســفيان عــن أبــي الزنــاد قــال ‪»:‬ســألت ســعيد بــن املســيب عــن الرجــل‬\n      ‫ال يجــد مــا ينفــق علــى امرأتــه ؟ قــال ‪ :‬يفــرق بينهمــا قــال أبــو الزنــاد‬\n      ‫لســعيد ‪ :‬ســنة ؟ قــال ســعيد ســنة» وألن هــذا أولــى بالفســخ مــن العجــز‬\n      ‫بالــوطء وكان علــى التراخــي ألنــه كخيــار العيــب)»‪ »560/5‬قــال يف‬\n\n\n‫‪237‬‬\n\f‫اإلنصــاف (قولــه‪« :‬وإن غــاب ولــم يتــرك لهــا نفقــة ولــم تقــدر لــه علــى مــال‬\n‫وال االســتدانة عليــه ‪:‬فلهــا الفســخ» هــذا املذهــب ‪ .‬جــزم بــه يف الوجيــز‬\n‫والنظــم ومنتخــب اآلدمــي وتذكــرة ابــن عبــدوس وغيرهــم وقدمــه يف‬\n‫املغنــي والشــرح والفــروع وغيرهــم» (كتــاب النفقــات ( ‪ )1638 /2‬طبعــة‬\n‫بيــت األفــكار وقــال أيض ـ ًا يف الكشــاف يف موضــع آخــر (فــإن تعــذر‬\n‫ذلــك اإلنفــاق عليهــا بــأن لــم يكــن نقــد ًا وال عرض ـ ًا وال عقــار ًا فلهــا‬\n‫الفســخ لتعــذر اإلنفــاق عليهــا مــن مالــه كحــال اإلعســار بــل هــذا أولــى‬\n‫بالفســخ ولــو فســخ احلاكــم نــكاح الزوجــة لفقــد مــال زوجهــا الغائــب‬\n‫ينفــق منــه ثــم تبــن لــه مــال ‪ .‬قــال ابــن نصــر اهلل يف حواشــي القواعــد‬\n‫الفقهيــة ‪:‬الظاهــر صحــة الفســخ وعــدم نقضــه ألن نفقتهــا إمنــا تتعلــق‬\n‫مبــا يقــدر عليــه مــن مــال زوجهــا وأمــا مــا كان غائب ـ ًا عنهــا ال علــم لهــا‬\n‫بــه فــا تكلــف الصبــر الحتمالــه)»‪ »5/563‬فقــد فســخت ‪ .........‬مــن‬\n‫‪ ..........‬وبــه حكمــت وجــرى النطــق بــه يف يــوم االثنــن ‪1433/2/11‬ه ـ‬\n‫وأفهمــت املدعيــة أن عليهــا العــدة الشــرعية حســب حالهــا وأن ال تتــزوج‬\n‫إال بعــد خروجهــا مــن العــدة و اكتســاب احلكــم الصفــة القطعيــة وقــد‬\n‫تولــى الترجمــة لهــا مترجــم احملكمــة محمــد إليــاس وأمــرت بإخــراج‬\n‫صــك مبــا تقــدم ورفعــه حملكمــة االســتئناف لتدقيقــه وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم احلمــد‬\n‫هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ويف يــوم‬\n‫الســبت ‪1434/4/27‬ه ـ فتــح ضبــط القضيــة الســاعة التاســعة بعدمــا‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار دائــرة األحــوال‬\n‫الشــخصية الثانيــة برقــم ‪ 34170320‬وتاريــخ ‪1434/3/24‬ه ـ ونــص‬\n‫احلاجــة منــه «وبدراســة الصــك صــورة ضبطــه تقــرر باألكثريــة إعادتهــا‬\n\n\n                                                                                         ‫‪238‬‬\n\f      ‫لفضيلــة حاكمهــا ملالحظــة مــا يلــي‪ -1 :‬حكــم علــى الــزوج وهــو لــم‬\n      ‫ا صحيحـ ًا يف الدعــوى ولــم يبــن يف حكمــه هــل‬       ‫يحضــر ولــم ميثــل متثيـ ً‬\n      ‫هــو غيابي ـ ًا أم حضوري ـ ًا ويجعــل املدعــى عليــه علــى حجتــه متــى حضــر‬\n      ‫والبــد مــن ذلــك ‪ -2 .‬لــم يبــن صفــة بينونــة املدعيــة مــن زوجهــا املذكــور‬\n      ‫وهــل هــي كبــرى أم صغــرى ويبــن احلكــم لهــا فيمــا لــو عــاد ورغــب‬\n      ‫كل منهمــا يف اآلخــر والبــد مــن ذلــك ‪ -3 .‬فضيلتــه ســأل الشــاهدين‬\n      ‫كيــف عرفــا إنــه لــم ينفــق علــى زوجتــه وأنــه تركهــا معلقــة ولــم يذكــر‬\n      ‫جوابهــا ال يف الضبــط وال يف الصــك فعلــى فضيلتــه إكمــال ذلــك ‪-4 .‬‬\n      ‫تصحيــح كلمــة مبوجــب الســجل املدنــي يف الســطر الثالــث مــن الصــك‬\n      ‫ولعــل صوابــه مبوجــب اإلقامــة رقــم واهلل املوفــق «أ‪.‬ه ـ عليــه أجيــب‬\n      ‫أصحــاب الفضيلــة وفقهــم اهلل لــكل خيــر مبــا يلــي أوالً‪ :‬فيمــا يخــص‬\n      ‫امللحوظــة األولــى والثانيــة فإنــي أضيــف علــى مــا حكمــت بــه مــا يلــي‬\n      ‫‪ :‬أوال ‪ /‬أفهمــت املدعيــة بأنهــا بانــت منــه بينونــة صغــرى ال حتــل لــه‬\n      ‫بعقــد جديــد مســتوف أركانــه وشــروطه ‪ .‬ثاني ـ ًا ‪ /‬أن احلكــم غيابــي‬\n      ‫والغائــب علــى حجتــه متــى حضــر ‪ .‬وأمــا امللحوظــة الثالثــة فــإن تدويــن‬\n      ‫الســؤال لهمــا كان باخلطــأ أثنــاء الضبــط ولــم حتــذف ســهوا حيــث‬\n      ‫جــرى تدويــن عالقــة الشــاهدين باملتداعيــن قبــل رصــد شــهادتهما حيــث‬\n      ‫أفــاد الشــاهد األول بأنــه شــقيق املدعيــة واآلخــر بأنــه صديقــه ومــن‬\n      ‫جماعتــه وعمــل بجــواره خمــس ســنوات ورأيــت االكتفــاء بذلــك وقــررت‬\n      ‫شــطب هــذه العبــارة ألنــه ال محــل لهــا ‪ .‬وأمــا امللحوظــة الرابعــة فقــد‬\n      ‫جــرى الــازم نحوهــا هــذا مــا لــزم اإلجابــة عليــه وأمــرت بإحلاقــه علــى‬\n      ‫الصــك وســجله وإعادتــه ألصحــاب الفضيلــة للتدقيــق كاملتبــع وصلــى‬\n      ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪ .‬احلمــد هلل‬\n\n\n‫‪239‬‬\n\f‫وحــده وبعــد ففــي يــوم األربعــاء ‪ 1434/06/28‬ه ـ فتــح ضبــط القضيــة‬\n‫الســاعة الثامنــة والربــع بعدمــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا القــرار رقــم ‪ 34223987‬وتاريــخ ‪1434/5/27‬ه ـ ونــص احلاجــة‬\n‫منــه ( وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم‬\n‫بعــد اجلــواب األخيــر واهلل املوفــق ‪.‬قاضــي اســتئناف ‪ ......‬ختمــه وتوقيعــه‬\n‫‪.‬قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه ‪ .‬رئيــس الدائــرة ‪ ...........‬ختمــه‬\n‫وتوقيعــه ) أ‪.‬ه ـ ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه وســلم‬\n                                                   ‫‪ .‬حــرر يف ‪ 1434/06/28‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n‫الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n‫علــى الصــك الصــادر مــن فضيلــة الشــيخ‪ ......... /‬القاضــي باحملكمــة‬\n‫العامــة باحملكمــة العامــة مبكــة املكرمــة املــؤرخ يف ‪1434/2/19‬ه ـ‬\n‫واملســجل بعــدد ‪ 3441536‬املتضمــن دعــوى‪ ......... /‬اجلنســية ضــد‪/‬‬\n‫‪ ..........‬بنجالديشــي اجلنســية يف فســخ نــكاح وبدراســة الصــك وصــورة‬\n‫ضبطــه تقــررت املوافقــة علــى احلكــم بعــد اجلــواب األخيــر واهلل املوفــق‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪240‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":233,"source_page_end":240,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2506ca86ce2a36905cf48c2e33844db7db9cdcacad96c4d8add24efb1c30ba09","normalized_text_hash":"3bf6c1decb783d65b1051b5b7a8ebd7f5a914f4feb174e8206b5496769aadc62","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p233-3441536"},{"id":"699481b4-c2d0-5b28-936f-ce4604c75b7b","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول -للتضرر من سجن الزوج -عدم موافقة الزوج -حصول الضرر للزوجة بترك الوطء مقتض للفسخ -من وجب عليه شيء وامتنع عن أدائه استوفاه عنه احلاكم -احلكم بفسخ النكاح .","document_number":"33108865","case_number":"32222418","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":"الدائرة الثانية املختصة بنظر قضايا األحوال الشخصية برقم","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/3/1","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول -للتضرر من سجن الزوج -عدم موافقة الزوج -حصول الضرر للزوجة بترك الوطء مقتض للفسخ -من وجب عليه شيء وامتنع عن أدائه استوفاه عنه احلاكم -احلكم بفسخ النكاح .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/3/1 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪33108865 :‬‬\n                        ‫َر ْق ُم الدعوى‪32222418 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34177359‬تاريخه‪1434/4/2:‬هـ‬\n\n\n      ‫فســخ نــكاح ‪ -‬طلــب الزوجــة فســخ النــكاح بعــد الدخــول ‪ -‬للتضــرر مــن‬\n      ‫ســجن الــزوج ‪ -‬عــدم موافقــة الــزوج ‪ -‬حصــول الضــرر للزوجــة بتــرك‬\n      ‫الــوطء مقتــض للفســخ ‪ -‬مــن وجــب عليــه شــيء وامتنــع عــن أدائــه‬\n                            ‫اســتوفاه عنــه احلاكــم ‪ -‬احلكــم بفســخ النــكاح ‪.‬‬\n\n\n\n\n                           ‫‪ .1‬قوله تعالى ‪ ( :‬وال تضاروهن لتضيقوا عليهن) ‪.‬‬\n                         ‫‪ .2‬قوله صلى اهلل عليه وسلم ‪( :‬ال ضرر وال ضرار ) ‪.‬‬\n      ‫‪ .3‬قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل‪( :‬وحصــول الضــرر للزوجــة‬\n      ‫بتــرك الــوطء مقتــض للفســخ بــكل حــال ســواء كان بقصــد مــن الــزوج‬\n      ‫أو بغيــر قصــد ولــو مــع قدرتــه وعجــزه كالنفقــة وأولــى للفســخ بتعــذره‬\n      ‫يف اإليــاء إجماع ـ ًا وعلــى هــذا فالقــول يف امــرأة األســير واحملبــوس‬\n      ‫ونحوهمــا ممــن تعــذر انتفــاع امرأتــه بــه إذا طلبــت فرقتــه كالقــول‬\n      ‫يف امــرأة املفقــود باإلجمــاع ) االختيــارات الفقهيــة (‪ )563/1‬والفتــاوى‬\n                                                               ‫الكبــرى (‪. )482/5‬‬\n      ‫‪ .4‬املــواد رقــم ‪ 10،7/34‬و‪ 5،4/176‬مــن نظــام املرافعــات الشــرعية‪،‬‬\n                                                       ‫ولوائحــه التنفيذيــة ‪.‬‬\n\n\n\n\n‫‪241‬‬\n\f‫ادعــت املدعيــة املعــرف بهــا مــن قبــل أخيهــا‪ ،‬أن املدعــى عليــه (ســجني)‬\n‫تزوجهــا علــى صــداق قــدره خمســة وعشــرون ألــف ريــال‪ ،‬ودخــل بهــا‬\n‫وأجنبــت منــه ولديــن‪ ،‬وأنــه عنــده بعــض التوجهــات املنحرفــة والتــي علــى‬\n‫إثرهــا أدخــل الســجن منــذ خمــس ســنوات‪ ،‬وأنهــا هــي التــي تصــرف على‬\n‫أوالدهــا منــذ ذلــك الوقــت‪ ،‬ولتضررهــا مــن ذلــك حيــث لــم تزره منذ ســنة‬\n‫ونصــف‪ ،‬طلبــت فســخ نكاحهــا منــه ‪ ،‬جــرى االطــاع علــى عقــد نكاح‬\n‫املدعيــة علــى املدعــى عليــه املتضمــن أنــه علــى صــداق قــدره خمســة‬\n‫وعشــرون ألــف ريــال ســعودي وبشــرط ســكن مســتقل للزوجــة ‪ ،‬بعرض‬\n‫الدعــوى علــى املدعــى عليــه صــادق علــى الــزواج‪ ،‬والصــداق‪ ،‬واألوالد‪،‬‬\n‫والســجن‪ ،‬وقــرر أنــه ســلمها مــن الصــداق عشــرين ألــف ريــال ‪ ،‬وأنــه‬\n‫ال يوافــق علــى طلبهــا الطــاق‪ ،‬وقــرر أنــه ســبق وأن طلقهــا ثــم راجعهــا‬\n‫‪ ،‬بعــرض ذلــك علــى املدعيــة أصــرت علــى طلبهــا ‪ ،‬يف جلســة أخــرى‬\n‫حضــرت املدعيــة ولــم يحضــر املدعــى عليــه ‪ ،‬نظــر ًا ألن بقــاء املدعيــة‬\n‫وزوجهــا يف الســجن فيــه ضــرر عليهــا ولقولــه تعالــى ( وال تضاروهــن‬\n‫لتضيقــوا عليهــن)‪ ،‬وحلديــث‪( :‬ال ضــرر وال ضــرار )‪ ،‬وقــد شــرع رفــع‬\n‫الضــرر بالفرقــة بــن الزوجــن ‪ ،‬والــزوج امتنــع مــن الطــاق ومــن وجــب‬\n‫عليــه شــيء وامتنــع عــن أدائــه اســتوفاه عنــه احلاكــم ‪ ،‬لــذا مت احلكــم‬\n‫بفســخ نــكاح املدعيــة مــن زوجهــا املدعــى عليــه بــا رجعــة ‪ -‬جــرى إفهــام‬\n‫املدعــى عليهــا أن عليهــا العــدة الشــرعية لهــذا الفســخ ابتــداء مــن تاريــخ‬\n‫احلكــم وأن ال تســتقبل اخلطــاب إال بعــد اكتســاب احلكــم القطعيــة‬\n‫وانتهــاء العــدة الشــرعية ‪ ،‬بعــرض احلكــم علــى املدعيــة قنعــت بــه ‪،‬‬\n\n                                                                                     ‫‪242‬‬\n\f      ‫حضــر املدعــى عليــه مــن الســجن وقــدم الئحتــه االعتراضيــة وباالطــاع‬\n      ‫عليهــا لــم يوجــد فيهــا مــا يؤثــر علــى احلكــم ‪ ،‬بعد رفــع احلكم حملكمة‬\n                                              ‫االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 32222418‬وتاريــخ ‪ 1432/06/12‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 32693290‬وتاريــخ ‪ 1432/06/12‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافــق‪ 1432/06/12‬ه ـ افتتحــت اجللســة وفيهــا حضــرت‬\n      ‫(‪ )........‬ميانيــة اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬املعــرف‬\n      ‫بهــا مــن قبــل أخيهــا (‪ )........‬مينــي اجلنســية مبوجــب رخصــة إقامــة رقــم‬\n      ‫(‪ )........‬لســماع دعواهــا ضــد (‪ )........‬والــذي يقيــم يف ســجن الطرفيــة‬\n      ‫بالقصيــم وقــد ادعــت قائلــة إن املدعــى عليــه زوجــي تزوجنــي بتاريــخ‬\n      ‫‪1425/11/10‬ه ـ علــى صــداق قــدره خمســة وعشــرون ألــف ريــال‬\n      ‫مبوجــب عقــد النــكاح الصــادر مــن محكمــة الضمــان واألنكحــة‬\n      ‫بالريــاض برقــم ‪..............‬يف ‪1424/4/9‬ه ـ وقــد دخــل بــي واجنبــت منــه‬\n      ‫‪ .........‬املولــود يف ‪1426/02/10‬ه ـ و‪ .......‬املولــود يف ‪1427/07/02‬ه ـ‬\n      ‫وقــد كان عنــده بعــض التوجهــات املنحرفــة والتــي علــى أثرهــا ادخــل‬\n      ‫الســجن منــذ خمــس ســنوات أي بتاريــخ ‪1427/10/05‬ه ـ بالقصيــم‬\n      ‫وأنــا أصــرف علــى أوالدي مــن ذلــك الوقــت أطلــب فســخ نكاحــي‬\n      ‫مــن املدعــى عليــه ولتضــرري مــن ذلــك فأنــا منــذ ســنة ونصــف لــم أقــم‬\n      ‫بزيارتــه هكــذا ادعــت‪ ،‬وقــد أبــرزت املدعيــة وثيقــة عقــد النــكاح‬\n\n‫‪243‬‬\n\f‫الصــادرة مــن احملكمــة اجلزئيــة للضمــان واألنكحــة بالريــاض برقــم‬\n‫………‪ ..‬يف ‪1424/4/9‬ه ـ واملتضمنــة عقــد نــكاح املدعيــة علــى‬\n‫املدعــى عليــه علــى صــداق قــدره خمســة وعشــرون ألــف ريــال ســعودي‬\n‫وبشــرط ســكن مســتقل للزوجــة فبنــاء علــى املــادة رقــم ‪10-7/34‬‬\n‫‪ 10/34‬فقــد قــررت اســتخالف رئيــس احملكمــة العامــة يف بريــدة أو‬\n‫مــن ينيبــه مــن أحــد قضــاة احملكمــة لســماع إجابــة املدعــى عليــه‪،‬‬\n‫ويف جلســة أخــرى بتاريخ‪1434/12/24‬ه ـ وبحضــور املدعيــة واملعــرف‬\n‫بهــا احلاضــر يف اجللســة الســابقة وحضــر حلضورهــا ‪ ...............‬مينــي‬\n‫اجلنســية يحمــل اإلقامــة رقــم ‪ ..................‬ولــم يحضــر مــن الســجن إال‬\n‫عنــد الســاعة العاشــرة والنصــف وبعــرض الدعــوى عليــه قــال إن املدعيــة‬\n‫زوجتــي تزوجتهــا بتاريــخ ‪1424 /11/08‬ه ـ علــى صــداق قــدره خمســة‬\n‫وعشــرون ألــف ريــال مبوجــب عقــد النــكاح الصــادر مــن محكمــة‬\n‫الضمــان واألنكحــة بالريــاض برقــم ‪ ...........‬يف ‪1424/4/9‬ه ـ وقــد‬\n‫ســلمت لهــا مبلــغ عشــرين ألــف ريــال وقــد دخلــت بهــا واجنبــت منهــا‬\n‫‪ .........‬املولــود يف ‪1426/02/10‬ه ـ و‪ .........‬املولــود يف ‪1427/07/02‬ه ـ‬\n‫وأنــا يف الســجن منــذ خمــس ســنوات بتاريــخ ‪1427/10/05‬ه ـ أمــا‬\n‫طلبهــا الطــاق فــا أوافــق علــى طالقهــا علمــا بأننــي قــد طلقتهــا يف‬\n‫‪1431/09/13‬ه ـ وراجعتهــا يف أواخــر شــهر ذي القعــده مــن نفــس العــام‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعيــه قالــت أطلــب فســخ نكاحــي‬\n‫لتضــرري مــن الســجن هكــذا أجابــت ثــم جــرت محاولــة بــن الزوجــن‬\n‫فأصــرت الزوجــه علــى طلبهــا وأصــر الــزوج علــى عــدم الطــاق‪ ،‬ويف‬\n‫جلســة أخــرى بتاريــخ ‪ 1433/2/29‬ه ـ حضــرت املدعيــة برفــق املعــرف‬\n‫بهــا احلاضــر يف اجللســة الســابقة ولــم يحضــر املدعــى عليــه رغــم طلبــه‬\n\n\n                                                                                    ‫‪244‬‬\n\f      ‫مــن الســجن يف اجللســة الســابقة وقــد قــررت املدعيــة قائلــة أطلــب فســخ‬\n      ‫نكاحــي مــن املدعــى عليــه لضــرري بذلــك هكــذا طلبــت فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن الزوجــة تطلــب فســخ نكاحهــا‬\n      ‫وقــد أصــرت علــى ذلــك وقــد رفــض الــزوج طلبهــا ومبــا أن الــزوج قــد‬\n      ‫أدخــل الســجن منــذ تاريــخ ‪1427/10/05‬ه ـ وألن بقائهــا طــول هــذه‬\n      ‫املــدة وزوجهــا يف الســجن فيــه ضــرر عليهــا ولقولــه تعالــى ( وال تضاروهن‬\n      ‫لتضيقــوا عليهــن ) وحلديــث ( ال ضــرر وال ضــرار ) وقــد شــرع رفــع‬\n      ‫الضــرر بالفرقــة بــن الزوجــن وملــا قــرره الفقهــاء بقولهــم ‪(:‬وحصــول‬\n      ‫الضــرر للزوجــة بتــرك الــوطء مقتــض للفســخ بــكل حــال ســواء كان‬\n      ‫بقصــد مــن الــزوج أو بغيــر قصــد ولــو مــع قدرتــه وعجــزه كالنفقــة وأولى‬\n      ‫للفســخ بتعــذره يف اإليــاء إجماعـ ًا وعلــى هــذا فالقــول يف امــرأة األســير‬\n      ‫واحملبــوس ونحوهمــا ممــن تعــذر انتفــاع امرأتــه بــه إذا طلبــت فرقتــه‬\n      ‫كالقــول يف امــرأة املفقــود باإلجمــاع ) االختيــارات الفقهيــة لشــيخ‬\n      ‫اإلســام ابــن تيميــة (‪ )563/1‬والفتــاوى الكبــرى (‪ )482/5‬وألن الــزوج‬\n      ‫امتنــع مــن الطــاق وألن مــن وجــب عليــه شــيء وامتنــع أدائــه اســتوفاه‬\n      ‫عنــه احلاكــم لذلــك كلــه فقــد فســخت نــكاح املدعيــة ‪ ...........‬مــن‬\n      ‫زوجهــا املدعــى عليــه ‪ .........‬بــا رجعــة وبذلــك قضيــت وأفهمتهــا بــأن‬\n      ‫عليهــا العــدة الشــرعية لهــذا الفســخ ابتــداء مــن تاريــخ احلكــم وهــي‬\n      ‫ثــاث حيــض فهــي مــن ذوات اإلقــراء بعــد ســؤالها وبعــرض احلكــم علــى‬\n      ‫املدعيــة قنعــت بــه وهــذا احلكــم يعــد حضوريــا علــى املدعــى عليــه نظــرا‬\n      ‫إلبالغــه شــخصيا يف اجللســة الســابقة وســنبعث نســخة مــن احلكــم‬\n      ‫للمدعــى عليــه بنــاء علــى املــادة ‪ 4/176‬مــن نظــام املرافعــات الشــرعية‬\n      ‫ولوائحــه التنفيذيــة لتقــدمي الئحتــه االعتراضيــة خــال مــدة ثالثــن يومــا‬\n\n\n‫‪245‬‬\n\f‫تبــدأ مــن إبالغــه وإن لــم يتقــدم خاللهــا بالئحتــه االعتراضيــة ســقط‬\n‫حقــه يف االعتــراض واكتســب احلكــم القطعيــة هــذا كمــا أفهمــت‬\n‫املدعيــة بــأن ال تســتقبل اخلطــاب إال بعــد اكتســاب احلكــم القطعيــة‬\n‫وانتهــاء العــدة الشــرعية‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/2/29‬ه ـ احلمــد هلل وحــده‬\n‫وبعــد ففــي يــوم الثالثــاء بتاريــخ ‪1433/08/20‬ه ـ افتتحــت اجللســة وقــد‬\n‫مت الكتابــة منــا إلــى صاحــب الســمو امللكــي أميــر منطقــة الريــاض‬\n‫مرتــن بكتابنــا رقــم ‪ 33/455646‬وتاريــخ ‪1433/3/9‬ه ـ وكتابنــا‬\n‫رقــم ‪ 33/735292‬وتاريــخ ‪1433/04/19‬ه ـ وذلــك لتبليــغ املدعــى‬\n‫عليــه باحلكــم الغيابــي ولــم تردنــا إفــادة حتــى تاريخــه لــذا قــررت رفــع‬\n‫احلكــم إلــى محكمــة االســتئناف لتعــذر إبــاغ املدعــى عليــه باحلكــم‬\n‫وفقــا للمــادة ‪ 5/ 176‬مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة‬\n‫‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                         ‫وســلم ‪ .‬حــرر يف ‪1433/08/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ :‬ففــي يــوم الثالثــاء ‪1433/12/21‬ه ـ افتتحــت‬\n‫اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف بكتابهــم رقــم‬\n‫‪ 331621886‬يف ‪1433/10/15‬هــ‪ ،‬وبرفقــه قــرار دائــرة األحــوال‬\n‫الشــخصية الثانيــة رقــم ‪ 33406783‬يف ‪1433/9/10‬ه ـ ونــص احلاجــة‬\n‫منــه‪( :‬وبدراســة صــورة ضبطــه وأوراق املعاملــة لوحــظ أن املدعــى عليــه‬\n‫ســجني ومحــل ســجنه معلــوم واملتعــن إجــراء مقتضــى الفقــرة الثالثــة مــن‬\n‫املــادة السادســة والســبعون بعــد املائــة مــن نظــام املرافعــات الشــرعية نحو‬\n‫إعالمــه باحلكــم واعتراضــه عليه)اهــ‪ .‬وعليــه أجيــب أصحــاب الفضيلــة‬\n‫بأنــه قــد متــت الكتابــة منــا إلــى صاحــب الســمو امللكــي أميــر منطقــة‬\n\n\n                                                                                     ‫‪246‬‬\n\f      ‫الريــاض ثــاث مــرات بكتابنــا رقــم ‪ 33/455646‬يف ‪1433/3/9‬ه ـ‬\n      ‫وكتابنــا رقــم ‪ 33/735292‬يف ‪1433/4/19‬ه ـ وكذلــك متــت الكتابــة‬\n      ‫بعــد قراركــم املرصــود أعــاه بكتابنــا رقــم ‪ 33/1974041‬يف‬\n      ‫‪1433/11/19‬ه ـ وذلــك لتبليــغ املدعــى عليــه باحلكــم الغيابــي ولــم‬\n      ‫تردنــا إفــادة حتــى تاريخــه لــذا قــررت رفــع احلكــم إلــى محكمــة‬\n      ‫االســتئناف لتعــذر إبــاغ املدعــى عليــه باحلكــم وفقــا للمــادة ‪5/176‬‬\n      ‫مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة وتضــرر املدعيــة مــن‬\n      ‫طــول املــدة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم‪ .‬حــرر يف ‪1433/12/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/02/05‬ه ـ‬\n      ‫افتتحــت اجللســة و قــد وردنــا كتــاب فضيلــة رئيس محكمة االســتئناف‬\n      ‫برقــم ‪ 3446778‬يف ‪1432/1/24‬ه ـ واملرفــق بــه القــرار الصــادر مــن‬\n      ‫الدائــرة الثانيــة املختصــة بنظــر قضايــا األحــوال الشــخصية برقــم‬\n      ‫‪ 349925‬يف ‪1434/1/12‬ه ـ ونــص احلاجــة منــه (و حيــث ســبق دراســة‬\n      ‫الصــك وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n      ‫فضيلتــه القاضــي و أحلقــه بالصــك بنــاء علــى قرارنــا رقــم ‪33406783‬‬\n      ‫وتاريــخ ‪1433/9/10‬ه ـ لوحــظ باألكثريــة أن مــا أجــراه فضيلتــه غيــر‬\n      ‫كاف و املتعــن إجــراء مــا يلــزم حيــال تبليــغ املدعــى عليــه مبتابعــة‬\n      ‫الكتابــة جلهــات االختصــاص لتطبيــق مــا نصــت عليــه العليمــات نحــو‬\n      ‫تبليــغ الســجني باحلكــم ) أه ـ وعليــه أجيــب أصحــاب الفضيلــة بأنــه أثناء‬\n      ‫رفــع املعاملــة لكــم قــد راجعنــا املدعــى عليــه مــن الســجن و قــدم الئحتــه‬\n      ‫االعتراضيــة املقيــدة يف احملكمــة برقم ‪ 34188508‬يف ‪1434/1/21‬هـ‬\n      ‫واملكونــة مــن ورقــة واحــدة مكتوبــة بخــط اليــد وباالطــاع عليهــا لــم‬\n\n\n‫‪247‬‬\n\f‫جنــد فيهــا مــا يؤثــر علــى مــا حكمــت بــه و مت بعثهــا لكــم بكتابنــا‬\n‫رقــم ‪ 34/207522‬وتاريــخ ‪1434/1/25‬ه ـ وقــررت إعــادة املعاملــة إلــى‬\n‫محكمــة االســتئناف و بــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/5‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق‪ 1434/03/09‬ه ـ‬\n‫افتتحــت اجللســة و قــد وردنــا كتــاب رئيــس محكمــة االســتئناف برقــم‬\n‫‪ 34394762‬يف ‪1434/3/3‬ه ـ برفقــة القــرار الصــادر مــن الدائــرة‬\n‫الثانيــة املختصــة بنظــر قضايــا األحــوال الشــخصية و اإلنهــاءات برقــم‬\n‫‪ 3445331‬يف ‪1434/2/24‬ه ـ و نــص احلاجــة منــه (و بدراســة الصــك‬\n‫وصــورة ضبطــه و أوراق املعاملــة و باالطــاع علــى مــا أجــاب بــه فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه و حيــث ســبق دراســة الصــك و صــورة‬\n‫ضبطــه و أوراق املعاملــة و باالطــاع علــى مــا أجــاب بــه فضيلتــه القاضــي‬\n‫و أحلقــه بالصــك بنــاء علــى قرارنــا رقــم ‪ 349925‬يف ‪1433/1/12‬ه ـ‬\n‫لوحــظ باألكثريــة أن ذكــر املدعــى عليــه يف الئحتــه االعتراضيــة أنــه‬\n‫ســيتم إطــاق ســراحه خــال شــهرين مــن تاريــخ ‪1434/1/21‬ه ـ لــذا‬\n‫البــد مــن الكتابــة إلــى اجلهــة املختصــة بالســجن لســؤالها عــن ذلــك و إذا‬\n‫كان األمــر كذلــك فــا بــد مــن عــرض األمــر علــى املدعيــة فــإن أصرت‬\n‫علــى طلــب الفســخ فــا بــد مــن بعــث حكمــن قبــل احلكــم بالفســخ أو‬\n‫عدمــه و اهلل املوفــق و صلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه أجمعــن ) أه ـ و عليــه فقــد حضــرت املدعيــة و املعــرف بهــا مــن‬\n‫قبــل ‪ ...........‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ……‪ ..‬و قالــت‬\n‫إننــي متضــررة و أطلــب فســخ نكاحــي منــه و مســتعدة بتســليم العــوض و‬\n‫هــو املهــر و قــدره خمســة وعشــرون ألــف ريــال ســعودي متــى طلبــه منــي‬\n\n\n                                                                                    ‫‪248‬‬\n\f      ‫املدعــى عليــه و هــو ديــن يف ذمتــي لــه و لــن أرجــع لــه البتــة هكــذا أجابــت‬\n      ‫وعليــه أجيــب أصحــاب الفضيلــة بأنــه لــم يظهــر لــي ســوى مــا حكمــت‬\n      ‫بــه مســببا و نصــه (ومبــا أن الــزوج قــد أدخــل الســجن منــذ تاريــخ‬\n      ‫‪1427/10/05‬ه ـ وألن بقائهــا طــول هــذه املــدة وزوجهــا يف الســجن فيــه‬\n      ‫ضــرر عليهــا ولقولــه تعالــى ( وال تضاروهــن لتضيقــوا عليهــن ) وحلديــث‬\n      ‫( ال ضــرر وال ضــرار ) وقــد شــرع رفــع الضــرر بالفرقــة بــن الزوجــن وملــا‬\n      ‫قــرره الفقهــاء بقولهــم ‪(:‬وحصــول الضــرر للزوجــة بتــرك الــوطء مقتــض‬\n      ‫للفســخ بــكل حــال ســواء كان بقصــد مــن الــزوج أو بغيــر قصــد ولــو‬\n      ‫مــع قدرتــه وعجــزه كالنفقــة وأولــى للفســخ بتعــذره يف اإليــاء إجماعـ ًا‬\n      ‫وعلــى هــذا فالقــول يف امــرأة األســير واحملبــوس ونحوهمــا ممــن تعــذر‬\n      ‫انتفــاع امرأتــه بــه إذا طلبــت فرقتــه كالقــول يف امــرأة املفقــود باإلجمــاع‬\n      ‫) االختيــارات الفقهيــة لشــيخ اإلســام ابــن تيميــة (‪ )563/1‬أه ـ و قــد‬\n      ‫قــررت إعــادة املعاملــة حملكمــة االســتئناف ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n      ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/3/9‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد يف هــذا اليــوم األحــد ‪1434/4/21‬ه ـ عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف بكتابهــم رقــم ‪ 34668033‬وتاريــخ‬\n      ‫‪1434/4/15‬ه ـ وبرفقــه القــرار رقــم ‪ 34177359‬وتاريــخ ‪1434/4/2‬ه ـ‬\n      ‫الصــادر مــن دائــرة األحــوال الشــخصية املتضمــن مــا نصــه ( تقــرر‬\n      ‫الدائــرة أنــه لــم يظهــر مــا يوجــب النقــض بعــد اجلــواب األخيــر ) أ‪.‬ه ـ‬\n      ‫لــذا جــرى إثباتــه واهلل املوفــق وصلــى اهلل وســلم علــى محمــد ‪ .‬حــرر يف‬\n                                                                        ‫‪1434/4/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n\n\n‫‪249‬‬\n\f‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد برقــم ‪ 34/597427‬وتاريــخ ‪1434/9/10‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪............../‬‬\n‫املســجل برقــم ‪ 33108865‬وتاريــخ ‪1433/3/1‬ه ـ اخلــاص بدعــوى‪/‬‬\n‫‪...........‬مينيــة اجلنســية ضــد‪ ......../‬ميانــي اجلنســية بشــأن فســخ نــكاح وقــد‬\n‫تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وحيــث‬\n‫ســبق دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالصــك‬\n‫بنــاء علــى قرارنــا رقــم ‪ 3445331‬وتاريــخ ‪1434/2/24‬ه ـ تقــرر الدائــرة‬\n‫باألكثريــة انــه لــم يظهــر مــا يوجــب النقــض بعــد اجلــواب األخيــر‪ .‬واهلل‬\n       ‫املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪250‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":241,"source_page_end":250,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6ba51b4523038fba0ef5292b5c3cdfc15bc74f6ef08fbbbcafce8fc77507a679","normalized_text_hash":"0eb3d251639e2340066cd2e0585835692bcba506d8df7885da2f04a473d99b01","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p241-33108865"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

